-- Isolated qualification only; NOT a deployable migration or source-admission path.
-- The trusted gateway supplies a verified Auth UUID. Workers/browser roles receive no access.
create role mip_hypothesis_owner nologin nosuperuser nocreatedb nocreaterole noinherit nobypassrls;
create role mip_hypothesis_gateway nologin nosuperuser nocreatedb nocreaterole noinherit nobypassrls;
create schema mip_hypothesis authorization mip_hypothesis_owner;
grant usage on schema evidence_pipeline to mip_hypothesis_owner;
grant select on evidence_pipeline.investigation_memberships to mip_hypothesis_owner;
create policy hypothesis_owner_membership_read on evidence_pipeline.investigation_memberships for select to mip_hypothesis_owner using(true);

set role mip_hypothesis_owner;
create table mip_hypothesis.revisions(
 id uuid primary key,
 investigation_id uuid not null,
 request_id uuid not null,
 author_id uuid not null,
 predecessor_id uuid,
 revision bigint not null check(revision>0),
 request_arguments jsonb not null,
 assessment jsonb not null,
 recorded_at timestamptz not null default clock_timestamp(),
 unique(investigation_id,id),
 unique(investigation_id,revision),
 unique(investigation_id,request_id),
 foreign key(investigation_id,predecessor_id) references mip_hypothesis.revisions(investigation_id,id),
 check(assessment->>'release_state' is not distinct from 'private'),
 check(assessment->>'contract_version' is not distinct from 'mip_hypothesis_assessment_v1')
);
alter table mip_hypothesis.revisions enable row level security;
alter table mip_hypothesis.revisions force row level security;
create policy owner_only on mip_hypothesis.revisions to mip_hypothesis_owner using(true) with check(true);
create function mip_hypothesis.reject_mutation() returns trigger language plpgsql set search_path='' as $$
begin raise exception using errcode='55000',message='hypothesis revisions are append-only'; end $$;
create trigger immutable_rows before update or delete on mip_hypothesis.revisions
 for each row execute function mip_hypothesis.reject_mutation();
create trigger immutable_table before truncate on mip_hypothesis.revisions
 for each statement execute function mip_hypothesis.reject_mutation();

create function mip_hypothesis.append_revision(p_user uuid,p_investigation uuid,p_request uuid,p_predecessor uuid,p_assessment jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare old mip_hypothesis.revisions; head mip_hypothesis.revisions; access text; result jsonb; new_id uuid;
 args jsonb; n bigint; cutoff timestamptz; acquired timestamptz; item jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 if p_user is null or p_investigation is null or p_request is null then
  raise exception using errcode='22023',message='missing assessment identity'; end if;
 -- Same fence used by the existing membership set_access RPC.
 perform pg_advisory_xact_lock(hashtextextended('mip-workspace-access:'||p_investigation::text||':'||p_user::text,0));
 select access_role into access from evidence_pipeline.investigation_memberships
  where investigation_id=p_investigation and user_id=p_user;
 if access is distinct from 'reviewer' then raise exception using errcode='42501',message='hypothesis append denied'; end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-hypothesis-question:'||p_investigation::text,0));
 args:=jsonb_build_object('predecessor',p_predecessor,'assessment',p_assessment);
 select * into old from mip_hypothesis.revisions where investigation_id=p_investigation and request_id=p_request;
 if found then
  if old.author_id<>p_user or old.request_arguments is distinct from args then
   raise exception using errcode='23505',message='hypothesis retry conflict'; end if;
  return old.assessment;
 end if;
 select * into head from mip_hypothesis.revisions where investigation_id=p_investigation order by revision desc limit 1;
 if head.id is distinct from p_predecessor then
  raise exception using errcode='40001',message='hypothesis predecessor changed'; end if;
 if jsonb_typeof(p_assessment) is distinct from 'object' or
    p_assessment->>'contract_version' is distinct from 'mip_hypothesis_assessment_v1' or
    p_assessment->>'release_state' is distinct from 'private' or
    p_assessment->>'review_state' is distinct from 'unreviewed' or
    p_assessment->>'question_id' is distinct from p_investigation::text or
    jsonb_typeof(p_assessment->'evidence') is distinct from 'array' or
    jsonb_typeof(p_assessment->'hypotheses') is distinct from 'array' then
  raise exception using errcode='22023',message='unsupported hypothesis envelope'; end if;
 if jsonb_array_length(p_assessment->'hypotheses')<2 then
  raise exception using errcode='22023',message='competing hypotheses required'; end if;
 if p_assessment->>'knowledge_cutoff' is null then
  raise exception using errcode='22023',message='missing knowledge cutoff'; end if;
 cutoff:=(p_assessment->>'knowledge_cutoff')::timestamptz;
 if not isfinite(cutoff) or cutoff>clock_timestamp() then
  raise exception using errcode='22023',message='future knowledge cutoff'; end if;
 for item in select value from jsonb_array_elements(p_assessment->'evidence') loop
  acquired:=(item->>'acquired_at')::timestamptz;
  if acquired is null or not isfinite(acquired) or acquired>cutoff then
   raise exception using errcode='22023',message='evidence outside knowledge boundary'; end if;
 end loop;
 n:=coalesce(head.revision,0)+1;
 new_id:=gen_random_uuid();
 -- Server assigns completed/recorded time; client identity/revision/time claims cannot backdate history.
 result:=p_assessment||jsonb_build_object('id',new_id,'revision',n,'predecessor_id',p_predecessor,
  'completed_at',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 insert into mip_hypothesis.revisions(id,investigation_id,request_id,author_id,predecessor_id,revision,request_arguments,assessment)
 values(new_id,p_investigation,p_request,p_user,p_predecessor,n,args,result);
 return result;
end $$;
create function mip_hypothesis.read_history(p_user uuid,p_investigation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare access text; result jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-workspace-access:'||p_investigation::text||':'||p_user::text,0));
 select access_role into access from evidence_pipeline.investigation_memberships
  where investigation_id=p_investigation and user_id=p_user;
 if access is null or access not in('viewer','reviewer') then
  raise exception using errcode='42501',message='hypothesis read denied'; end if;
 select coalesce(jsonb_agg(assessment order by revision),'[]'::jsonb) into result
  from mip_hypothesis.revisions where investigation_id=p_investigation;
 return result;
end $$;
revoke all on all tables in schema mip_hypothesis from public;
revoke all on all functions in schema mip_hypothesis from public;
grant usage on schema mip_hypothesis to mip_hypothesis_gateway;
grant execute on function mip_hypothesis.append_revision(uuid,uuid,uuid,uuid,jsonb),
 mip_hypothesis.read_history(uuid,uuid) to mip_hypothesis_gateway;
reset role;

-- Isolated adapter over existing retained workspace observations; no new permission registry.
grant select on evidence_pipeline.investigation_versions,evidence_pipeline.investigation_observations to mip_hypothesis_owner;
create policy hypothesis_version_reader on evidence_pipeline.investigation_versions for select to mip_hypothesis_owner using(true);
create policy hypothesis_observation_reader on evidence_pipeline.investigation_observations for select to mip_hypothesis_owner using(true);
grant usage on schema mip_identity to mip_hypothesis_owner;
grant execute on function mip_identity.operation_check(jsonb) to mip_hypothesis_owner;
set role mip_hypothesis_owner;
create function mip_hypothesis.observation_binding(p_user uuid,p_investigation uuid,p_version uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare access text; v evidence_pipeline.investigation_versions; o evidence_pipeline.investigation_observations;
 inputs jsonb:='[]'; i jsonb; rec jsonb; meta jsonb; kind text;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-workspace-access:'||p_investigation::text||':'||p_user::text,0));
 select access_role into access from evidence_pipeline.investigation_memberships where investigation_id=p_investigation and user_id=p_user;
 if access is null or access not in ('viewer','reviewer') then raise exception using errcode='42501',message='hypothesis read denied';end if;
 select * into v from evidence_pipeline.investigation_versions where id=p_version and investigation_id=p_investigation;
 if not found then raise exception using errcode='42501',message='hypothesis version denied';end if;
 select * into strict o from evidence_pipeline.investigation_observations where id=v.observation_id;
 for i in select value from jsonb_array_elements(o.snapshot->'inputs') loop
  if (i->'capture' is null or i->'capture'='null'::jsonb)=(i->'record_version' is null or i->'record_version'='null'::jsonb) then
   raise exception using errcode='22023',message='ambiguous retained input';end if;
  kind:=case when i->'capture' is not null and i->'capture'<>'null'::jsonb then 'capture' else 'record_version' end;
  rec:=i->kind;
  meta:=(rec-'payload')||jsonb_build_object(
   'source_version_hash',encode(sha256(convert_to(rec::text,'UTF8')),'hex'),
   'payload',jsonb_strip_nulls(jsonb_build_object('published_at',rec->'payload'->'published_at','event_time',rec->'payload'->'event_time')));
  -- Only identity/time fields plus a native digest leave the DB before permission checks.
  inputs:=inputs||jsonb_build_array(jsonb_build_object('position',i->>'position',kind,
   jsonb_build_object('id',meta->>'id','captured_at',case when kind='capture' then to_char((rec->>'captured_at')::timestamptz at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,'recorded_at',case when kind='record_version' then to_char((rec->>'recorded_at')::timestamptz at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,
    'source_version_hash',meta->>'source_version_hash','payload',meta->'payload')));
 end loop;
 return jsonb_build_object('investigation_id',p_investigation,'access_role',access,
  'version',jsonb_build_object('id',v.id,'observation_id',o.id,'state',jsonb_build_object('question',v.state->>'question')),
  'observation',jsonb_build_object('id',o.id,'snapshot',jsonb_build_object('contract_version','investigation-observation-1','publicly_eligible',false,'inputs',inputs)));
end $$;
create function mip_hypothesis.operation_permission(p_user uuid,p_investigation uuid,p_version uuid,p_position text,
 p_source_project text,p_operation text,p_domain text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare binding jsonb; i jsonb; rec jsonb; kind text; scope jsonb;
begin
 binding:=mip_hypothesis.observation_binding(p_user,p_investigation,p_version);
 if p_source_project is null or btrim(p_source_project)='' or p_source_project='cc-definition-batch-v1' then
  raise exception using errcode='42501',message='hypothesis source scope unavailable';end if;
 if p_operation is null or p_operation not in('retention','analysis','excerpt_display') or p_domain is null or p_domain not in('rights','privacy') then
  raise exception using errcode='42501',message='hypothesis operation denied';end if;
 if (select count(*) from jsonb_array_elements(binding->'observation'->'snapshot'->'inputs') x where x->>'position'=p_position)<>1 then
  raise exception using errcode='22023',message='retained identity missing or ambiguous';end if;
 select value into strict i from jsonb_array_elements(binding->'observation'->'snapshot'->'inputs') where value->>'position'=p_position;
 kind:=case when i ? 'capture' then 'capture' else 'record_version' end;rec:=i->kind;
 scope:=jsonb_build_object('source_project',p_source_project,'material_ref',kind||':'||(rec->>'id'),
  'material_version',rec->>'source_version_hash','source_version',rec->>'id',
  'audience','isolated_internal_review','operation',p_operation,'domain',p_domain);
 return mip_identity.operation_check(scope);
end $$;
create function mip_hypothesis.retained_excerpt(p_user uuid,p_investigation uuid,p_version uuid,p_position text,
 p_source_project text,p_field text,p_start integer,p_end integer,p_expected_hash text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare binding jsonb; v evidence_pipeline.investigation_versions; o evidence_pipeline.investigation_observations;
 i jsonb; rec jsonb; kind text; digest text; scope jsonb; result jsonb; operation text; domain text; raw text; passage text;
begin
 -- Auth/membership is independently rechecked at the sensitive content read.
 binding:=mip_hypothesis.observation_binding(p_user,p_investigation,p_version);
 if p_source_project is null or btrim(p_source_project)='' or p_source_project='cc-definition-batch-v1' then
  raise exception using errcode='42501',message='hypothesis source scope unavailable';end if;
 if p_field is null or p_field not in('title','summary','body_text') or p_start is null or p_end is null or p_start<0 or p_end<=p_start
 or p_expected_hash is null or p_expected_hash !~ '^[0-9a-f]{64}$' then
  raise exception using errcode='22023',message='invalid retained span';end if;
 select * into strict v from evidence_pipeline.investigation_versions where id=p_version and investigation_id=p_investigation;
 select * into strict o from evidence_pipeline.investigation_observations where id=v.observation_id;
 if (select count(*) from jsonb_array_elements(o.snapshot->'inputs') x where x->>'position'=p_position)<>1 then
  raise exception using errcode='22023',message='retained identity missing or ambiguous';end if;
 select value into strict i from jsonb_array_elements(o.snapshot->'inputs') where value->>'position'=p_position;
 kind:=case when i->'capture' is not null and i->'capture'<>'null'::jsonb then 'capture' else 'record_version' end;
 rec:=i->kind;digest:=encode(sha256(convert_to(rec::text,'UTF8')),'hex');
 foreach operation in array array['retention','analysis','excerpt_display'] loop
 foreach domain in array array['rights','privacy'] loop
  scope:=jsonb_build_object('source_project',p_source_project,'material_ref',kind||':'||(rec->>'id'),
   'material_version',digest,'source_version',rec->>'id','audience','isolated_internal_review','operation',operation,'domain',domain);
  result:=mip_identity.operation_check(scope);
  if result->'allowed' is distinct from 'true'::jsonb or (
   (result->'synthetic'='true'::jsonb and result->>'reason'='synthetic_mechanism_only') or
   (result->'synthetic'='false'::jsonb and result->>'reason'='real_evidence_bound' and nullif(result->>'admission_revision','') is not null
    and result->>'material_hash'=digest and jsonb_typeof(result->'primary_evidence_refs')='array' and jsonb_array_length(result->'primary_evidence_refs')>0)
  ) is distinct from true then
   raise exception using errcode='42501',message='hypothesis operation denied';end if;
 end loop;end loop;
 -- operation_check holds its existing permission/revocation fence through transaction end.
 raw:=rec->'payload'->>p_field;
 if raw is null or p_end>char_length(raw) then raise exception using errcode='22023',message='retained span out of bounds';end if;
 passage:=substring(raw from p_start+1 for p_end-p_start);
 if encode(sha256(convert_to(passage,'UTF8')),'hex')<>p_expected_hash then
  raise exception using errcode='22023',message='retained span hash mismatch';end if;
 return jsonb_build_object('excerpt',passage,'material_hash',digest,'material_version',rec->>'id',
  'input_position',p_position,'source_field',p_field,'start',p_start,'end',p_end);
end $$;
revoke all on function mip_hypothesis.operation_permission(uuid,uuid,uuid,text,text,text,text),mip_hypothesis.observation_binding(uuid,uuid,uuid),
 mip_hypothesis.retained_excerpt(uuid,uuid,uuid,text,text,text,integer,integer,text) from public;
grant execute on function mip_hypothesis.operation_permission(uuid,uuid,uuid,text,text,text,text),mip_hypothesis.observation_binding(uuid,uuid,uuid),
 mip_hypothesis.retained_excerpt(uuid,uuid,uuid,text,text,text,integer,integer,text) to mip_hypothesis_gateway;
reset role;

-- Atomic isolated acceptance over the retained-observation reader and existing permission fence.
grant select,update on mip_cutover_authority.publication_fence to mip_hypothesis_owner;
create policy hypothesis_fence_owner on mip_cutover_authority.publication_fence to mip_hypothesis_owner using(true) with check(true);
grant select on evidence_pipeline.investigations,evidence_pipeline.change_subjects to mip_hypothesis_owner;
create policy hypothesis_head_reader on evidence_pipeline.investigations for select to mip_hypothesis_owner using(true);
grant references on evidence_pipeline.investigation_versions,evidence_pipeline.investigation_observations to mip_hypothesis_owner;
grant usage on schema mip_cutover_authority to mip_hypothesis_owner;
-- change_subjects is SECURITY INVOKER. Its owner receives only the columns it actually reads.
grant select(position,capture_id,record_version_id) on evidence_pipeline.evidence_changes to mip_hypothesis_owner;
grant select(id,article_id) on evidence_pipeline.article_captures to mip_hypothesis_owner;
grant select(id,record_kind,record_key) on evidence_pipeline.record_versions to mip_hypothesis_owner;
create policy hypothesis_change_reader on evidence_pipeline.evidence_changes for select to mip_hypothesis_owner using(true);
create policy hypothesis_capture_identity_reader on evidence_pipeline.article_captures for select to mip_hypothesis_owner using(true);
create policy hypothesis_record_identity_reader on evidence_pipeline.record_versions for select to mip_hypothesis_owner using(true);
grant select(id,candidate_id) on evidence_pipeline.assessments to mip_hypothesis_owner;
create policy hypothesis_assessment_identity_reader on evidence_pipeline.assessments for select to mip_hypothesis_owner using(true);
set role mip_hypothesis_owner;
create table mip_hypothesis.acceptance_bindings(
 revision_id uuid primary key references mip_hypothesis.revisions(id),
 workspace_version_id uuid not null references evidence_pipeline.investigation_versions(id),
 observation_id uuid not null references evidence_pipeline.investigation_observations(id),
 source_project text not null,
 metadata jsonb not null,
 recorded_at timestamptz not null default clock_timestamp()
);
alter table mip_hypothesis.acceptance_bindings enable row level security;
alter table mip_hypothesis.acceptance_bindings force row level security;
create policy owner_only on mip_hypothesis.acceptance_bindings to mip_hypothesis_owner using(true) with check(true);
create trigger immutable_rows before update or delete on mip_hypothesis.acceptance_bindings
 for each row execute function mip_hypothesis.reject_mutation();
create trigger immutable_table before truncate on mip_hypothesis.acceptance_bindings
 for each statement execute function mip_hypothesis.reject_mutation();

create function mip_hypothesis.source_change_fence() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for update;
 return null;
end $$;
create function mip_hypothesis.context_current(p_investigation uuid,p_version uuid,p_observation uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from evidence_pipeline.investigations where id=p_investigation and current_version_id=p_version)
 and not exists(
  select 1 from evidence_pipeline.investigation_observations o
  cross join lateral jsonb_array_elements_text(o.snapshot->'watch_keys') k
  join evidence_pipeline.change_subjects s on s.watch_key=k.value
  where o.id=p_observation and not exists(
   select 1 from jsonb_array_elements(o.snapshot->'inputs') i where i->>'position'=s.position::text
  )
 )
 and not exists(
  select 1 from evidence_pipeline.investigation_observations o
  cross join lateral jsonb_array_elements(o.snapshot->'assessments') saved
  join evidence_pipeline.assessments current_assessment on current_assessment.candidate_id=(saved->>'candidate_id')::uuid
  where o.id=p_observation and not exists(
   select 1 from jsonb_array_elements(o.snapshot->'assessments') retained where retained->>'id'=current_assessment.id::text
  )
 )
$$;
create function mip_hypothesis.append_bound_revision(p_user uuid,p_investigation uuid,p_version uuid,p_source_project text,
 p_request uuid,p_predecessor uuid,p_assessment jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare b jsonb; e jsonb; i jsonb; rec jsonb; kind text; span jsonb; passage jsonb; checked jsonb;
 operation text; domain text; permissions jsonb; bindings jsonb:='[]'; result jsonb;
 prior mip_hypothesis.revisions; receipt mip_hypothesis.acceptance_bindings; observation uuid; current_context boolean;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 if p_source_project is null or btrim(p_source_project)='' or p_source_project='cc-definition-batch-v1' then raise exception using errcode='42501',message='hypothesis source scope unavailable';end if;
 -- Source/head changes and permission revocation all serialize against this same pre-existing fence.
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 b:=mip_hypothesis.observation_binding(p_user,p_investigation,p_version);
 if b->>'access_role'<>'reviewer' then raise exception using errcode='42501',message='hypothesis append denied';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-hypothesis-question:'||p_investigation::text,0));
 observation:=(b->'observation'->>'id')::uuid;
 select * into prior from mip_hypothesis.revisions where investigation_id=p_investigation and request_id=p_request;
 if found then
  select * into receipt from mip_hypothesis.acceptance_bindings where revision_id=prior.id;
  if not found or receipt.workspace_version_id<>p_version or receipt.source_project<>p_source_project then
   raise exception using errcode='23505',message='bound hypothesis retry conflict';end if;
 end if;
 current_context:=mip_hypothesis.context_current(p_investigation,p_version,observation);
 if prior.id is null and not current_context then raise exception using errcode='40001',message='hypothesis context changed; reassessment required';end if;
 if p_assessment->>'question' is distinct from b->'version'->'state'->>'question' then
  raise exception using errcode='22023',message='hypothesis question binding mismatch';end if;
 if p_assessment->'comparison'->>'state'='better_supported' and exists(
  select 1 from jsonb_array_elements_text(p_assessment->'comparison'->'favored_ids') favored
  where not exists(select 1 from jsonb_array_elements(p_assessment->'arguments') a
   where a->>'hypothesis_id'=favored.value and a->>'relation'='supports' and jsonb_array_length(a->'evidence_ids')>0)
 ) then raise exception using errcode='22023',message='favored hypothesis requires a supporting argument';end if;
 for e in select value from jsonb_array_elements(p_assessment->'evidence') loop
  if (select count(*) from jsonb_array_elements(b->'observation'->'snapshot'->'inputs') x where x->>'position'=e->>'input_position')<>1 then
   raise exception using errcode='22023',message='hypothesis input binding mismatch';end if;
  select value into strict i from jsonb_array_elements(b->'observation'->'snapshot'->'inputs') where value->>'position'=e->>'input_position';
  kind:=case when i ? 'capture' then 'capture' else 'record_version' end;rec:=i->kind;span:=e->'source_span';
  if rec->>'id' is distinct from e->>'material_version' or
   (e->>'acquired_at')::timestamptz is distinct from (coalesce(rec->>'captured_at',rec->>'recorded_at'))::timestamptz or
   coalesce(e->'published_at','null'::jsonb) is distinct from coalesce(rec->'payload'->'published_at','null'::jsonb) or
   coalesce(e->'event_time','null'::jsonb) is distinct from coalesce(rec->'payload'->'event_time','null'::jsonb) then
   raise exception using errcode='22023',message='hypothesis version or time binding mismatch';end if;
  passage:=mip_hypothesis.retained_excerpt(p_user,p_investigation,p_version,e->>'input_position',p_source_project,
   span->>'source_field',(span->>'start')::integer,(span->>'end')::integer,span->>'excerpt_sha256');
  permissions:='[]';
  foreach operation in array array['retention','analysis','excerpt_display'] loop
  foreach domain in array array['rights','privacy'] loop
   checked:=mip_hypothesis.operation_permission(p_user,p_investigation,p_version,e->>'input_position',p_source_project,operation,domain);
   if checked->'allowed' is distinct from 'true'::jsonb then raise exception using errcode='42501',message='hypothesis operation denied';end if;
   permissions:=permissions||jsonb_build_array(jsonb_build_object('operation',operation,'domain',domain,
    'revision',checked->'revision','admission_revision',checked->'admission_revision','synthetic',checked->'synthetic'));
  end loop;end loop;
  -- No new source-text copy in the binding receipt.
  bindings:=bindings||jsonb_build_array((passage-'excerpt')||jsonb_build_object('evidence_id',e->>'id','permissions',permissions));
 end loop;
 result:=mip_hypothesis.append_revision(p_user,p_investigation,p_request,p_predecessor,p_assessment);
 if prior.id is null then
  insert into mip_hypothesis.acceptance_bindings(revision_id,workspace_version_id,observation_id,source_project,metadata)
   values((result->>'id')::uuid,p_version,observation,p_source_project,bindings);
 else
  current_context:=current_context and receipt.metadata=bindings;
 end if;
 return jsonb_build_object('assessment',result,'workspace_version_id',p_version,'observation_id',observation,
  'current_context',current_context,'reassessment_pending',not current_context,'publication_allowed',false);
end $$;
revoke all on all functions in schema mip_hypothesis from public;
revoke all on mip_hypothesis.acceptance_bindings from public;
revoke execute on function mip_hypothesis.append_revision(uuid,uuid,uuid,uuid,jsonb) from mip_hypothesis_gateway;
grant execute on function mip_hypothesis.append_bound_revision(uuid,uuid,uuid,text,uuid,uuid,jsonb) to mip_hypothesis_gateway;
reset role;
create trigger hypothesis_change_fence before insert or update or delete or truncate on evidence_pipeline.evidence_changes
 for each statement execute function mip_hypothesis.source_change_fence();
create trigger hypothesis_workspace_fence before update or delete on evidence_pipeline.investigations
 for each statement execute function mip_hypothesis.source_change_fence();

-- Isolated permission-checked historical delivery. No public route or historical-time claim.
set role mip_hypothesis_owner;
create function mip_hypothesis.read_bound_history(p_user uuid,p_investigation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare access text; r mip_hypothesis.revisions; b mip_hypothesis.acceptance_bindings; item jsonb;
 e jsonb; permission jsonb; check_result jsonb; passage jsonb; allowed boolean; reason text; current_context boolean;
 result jsonb:='[]';
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 perform pg_advisory_xact_lock(hashtextextended('mip-workspace-access:'||p_investigation::text||':'||p_user::text,0));
 select access_role into access from evidence_pipeline.investigation_memberships where investigation_id=p_investigation and user_id=p_user;
 if access is null or access not in('viewer','reviewer') then raise exception using errcode='42501',message='hypothesis read denied';end if;
 for r in select * from mip_hypothesis.revisions where investigation_id=p_investigation order by revision loop
  item:=jsonb_build_object('revision_id',r.id,'revision',r.revision,'completed_at',r.assessment->>'completed_at');
  select * into b from mip_hypothesis.acceptance_bindings where revision_id=r.id;
  if not found then
   result:=result||jsonb_build_array(item||jsonb_build_object('status','withheld','reason','missing_acceptance_binding'));
   continue;
  end if;
  allowed:=true;reason:=null;
  -- The original receipt is a binding, never enduring permission to reveal a rationale.
  for e in select value from jsonb_array_elements(b.metadata) loop
   begin
    passage:=mip_hypothesis.retained_excerpt(p_user,p_investigation,b.workspace_version_id,e->>'input_position',b.source_project,
      e->>'source_field',(e->>'start')::int,(e->>'end')::int,
      (select v->'source_span'->>'excerpt_sha256' from jsonb_array_elements(r.assessment->'evidence') v where v->>'id'=e->>'evidence_id'));
   exception when insufficient_privilege or invalid_parameter_value or no_data_found then
    allowed:=false;reason:='current_permission_or_binding_denied';exit;
   end;
   for permission in select value from jsonb_array_elements(e->'permissions') loop
    check_result:=mip_hypothesis.operation_permission(p_user,p_investigation,b.workspace_version_id,e->>'input_position',b.source_project,
      permission->>'operation',permission->>'domain');
    if check_result->'allowed' is distinct from 'true'::jsonb then
     allowed:=false;reason:='current_permission_or_binding_denied';exit;
    elsif check_result->'revision' is distinct from permission->'revision' or
      coalesce(check_result->'admission_revision','null'::jsonb) is distinct from coalesce(permission->'admission_revision','null'::jsonb) then
     allowed:=false;reason:='permission_binding_changed_fresh_review_required';exit;
    end if;
   end loop;
   exit when not allowed;
  end loop;
  if not allowed then
   result:=result||jsonb_build_array(item||jsonb_build_object('status','withheld','reason',reason));
   continue;
  end if;
  current_context:=mip_hypothesis.context_current(p_investigation,b.workspace_version_id,b.observation_id);
  result:=result||jsonb_build_array(item||jsonb_build_object('status','available','assessment',r.assessment,
   'workspace_version_id',b.workspace_version_id,'observation_id',b.observation_id,
   'current_context',current_context,'reassessment_pending',not current_context));
 end loop;
 return jsonb_build_object('contract_version','mip_hypothesis_history_v1','investigation_id',p_investigation,
  'entries',result,'temporal_scope','retained_versions_only','historical_commit_visibility_qualified',false,'publication_allowed',false);
end $$;
revoke all on function mip_hypothesis.read_bound_history(uuid,uuid) from public;
revoke execute on function mip_hypothesis.read_history(uuid,uuid) from mip_hypothesis_gateway;
grant execute on function mip_hypothesis.read_bound_history(uuid,uuid) to mip_hypothesis_gateway;
reset role;

-- Isolated reassessment cause ledger over existing retained changes and permission heads.
-- No semantic assessment, worker, schedule, policy approval, source copy or live migration.
grant references on evidence_pipeline.evidence_changes to mip_hypothesis_owner;
set role mip_hypothesis_owner;
create table mip_hypothesis.reassessment_causes(
 id uuid primary key default gen_random_uuid(),
 investigation_id uuid not null,
 revision_id uuid not null references mip_hypothesis.revisions(id),
 cause_key text not null,
 kind text not null check(kind in('retained_source_change','retained_assessment_change','workspace_changed','permission_changed')),
 change_position bigint references evidence_pipeline.evidence_changes(position),
 related_version_id uuid,
 detail jsonb not null check(jsonb_typeof(detail)='object'),
 recorded_at timestamptz not null default clock_timestamp(),
 unique(revision_id,cause_key),
 check((kind='retained_source_change')=(change_position is not null))
);
create index reassessment_causes_question on mip_hypothesis.reassessment_causes(investigation_id,recorded_at,id);
alter table mip_hypothesis.reassessment_causes enable row level security;
alter table mip_hypothesis.reassessment_causes force row level security;
create policy owner_only on mip_hypothesis.reassessment_causes to mip_hypothesis_owner using(true) with check(true);
create trigger immutable_rows before update or delete on mip_hypothesis.reassessment_causes
 for each row execute function mip_hypothesis.reject_mutation();
create trigger immutable_table before truncate on mip_hypothesis.reassessment_causes
 for each statement execute function mip_hypothesis.reject_mutation();

create function mip_hypothesis.discover_reassessment_causes(p_investigation uuid) returns void
language plpgsql security definer set search_path='' as $$
declare r mip_hypothesis.revisions; b mip_hypothesis.acceptance_bindings; o evidence_pipeline.investigation_observations;
 head uuid; e jsonb; p jsonb; input jsonb; kind text; scope jsonb; checked jsonb; reason text; key text;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 -- Same order as acceptance, current source/head mutation and permission revocation.
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 if not found then raise exception using errcode='55000',message='hypothesis fence unavailable';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-hypothesis-question:'||p_investigation::text,0));
 select * into r from mip_hypothesis.revisions where investigation_id=p_investigation order by revision desc limit 1;
 if not found then return;end if;
 select * into b from mip_hypothesis.acceptance_bindings where revision_id=r.id;
 if not found then return;end if; -- Historical unbound primitives remain unavailable through the bound reader.
 select * into strict o from evidence_pipeline.investigation_observations where id=b.observation_id;
 -- Anti-membership, never a sequence/time watermark: old missed positions remain discoverable.
 insert into mip_hypothesis.reassessment_causes(investigation_id,revision_id,cause_key,kind,change_position,detail)
 select distinct p_investigation,r.id,'source:'||s.position::text,'retained_source_change',s.position,
  jsonb_build_object('observation_id',o.id,'input_change_position',s.position::text,'classification','requires_retained_evidence_review')
 from jsonb_array_elements_text(o.snapshot->'watch_keys') k
 join evidence_pipeline.change_subjects s on s.watch_key=k.value
 where not exists(select 1 from jsonb_array_elements(o.snapshot->'inputs') i where i->>'position'=s.position::text)
 on conflict(revision_id,cause_key) do nothing;
 insert into mip_hypothesis.reassessment_causes(investigation_id,revision_id,cause_key,kind,related_version_id,detail)
 select distinct p_investigation,r.id,'assessment:'||a.id::text,'retained_assessment_change',a.id,
  jsonb_build_object('observation_id',o.id,'retained_candidate_id',a.candidate_id,'assessment_version_id',a.id,
   'classification','requires_method_and_reasoning_review')
 from jsonb_array_elements(o.snapshot->'assessments') saved
 join evidence_pipeline.assessments a on a.candidate_id=(saved->>'candidate_id')::uuid
 where not exists(select 1 from jsonb_array_elements(o.snapshot->'assessments') retained where retained->>'id'=a.id::text)
 on conflict(revision_id,cause_key) do nothing;
 select current_version_id into head from evidence_pipeline.investigations where id=p_investigation;
 if head is distinct from b.workspace_version_id then
  insert into mip_hypothesis.reassessment_causes(investigation_id,revision_id,cause_key,kind,related_version_id,detail)
  values(p_investigation,r.id,'workspace:'||coalesce(head::text,'missing'),'workspace_changed',head,
   jsonb_build_object('accepted_workspace_version',b.workspace_version_id,'observed_workspace_version',head))
  on conflict(revision_id,cause_key) do nothing;
 end if;
 for e in select value from jsonb_array_elements(b.metadata) loop
  select value into strict input from jsonb_array_elements(o.snapshot->'inputs') i where i->>'position'=e->>'input_position';
  kind:=case when input->'capture' is not null and input->'capture'<>'null'::jsonb then 'capture' else 'record_version' end;
  for p in select value from jsonb_array_elements(e->'permissions') loop
   scope:=jsonb_build_object('source_project',b.source_project,'material_ref',kind||':'||(e->>'material_version'),
    'material_version',e->>'material_hash','source_version',e->>'material_version','audience','isolated_internal_review',
    'operation',p->>'operation','domain',p->>'domain');
   checked:=mip_identity.operation_check(scope);
   reason:=case when checked->'allowed' is distinct from 'true'::jsonb then 'current_permission_denied'
    when checked->'revision' is distinct from p->'revision' or
      coalesce(checked->'admission_revision','null'::jsonb) is distinct from coalesce(p->'admission_revision','null'::jsonb)
    then 'permission_binding_changed' else null end;
   if reason is not null then
    key:='permission:'||encode(sha256(convert_to(scope::text,'UTF8')),'hex')||':'||
      coalesce(checked->>'revision','missing')||':'||reason;
    insert into mip_hypothesis.reassessment_causes(investigation_id,revision_id,cause_key,kind,detail)
    values(p_investigation,r.id,key,'permission_changed',jsonb_build_object(
     'input_position',e->>'input_position','operation',p->>'operation','domain',p->>'domain',
     'accepted_permission_revision',p->'revision','observed_permission_revision',checked->'revision','reason',reason))
    on conflict(revision_id,cause_key) do nothing;
   end if;
  end loop;
 end loop;
end $$;

create function mip_hypothesis.reassessment_change_trigger() returns trigger
language plpgsql security definer set search_path='' as $$
declare iid uuid; scope jsonb;
begin
 if tg_table_schema='evidence_pipeline' and tg_table_name='evidence_changes' then
  for iid in
   select distinct r.investigation_id from mip_hypothesis.revisions r
   join mip_hypothesis.acceptance_bindings b on b.revision_id=r.id
   join evidence_pipeline.investigation_observations o on o.id=b.observation_id
   where not exists(select 1 from mip_hypothesis.revisions newer where newer.investigation_id=r.investigation_id and newer.revision>r.revision)
    and exists(select 1 from evidence_pipeline.change_subjects s
      where s.position=new.position and o.snapshot->'watch_keys' ? s.watch_key)
  loop perform mip_hypothesis.discover_reassessment_causes(iid);end loop;
 elsif tg_table_schema='evidence_pipeline' and tg_table_name='assessments' then
  for iid in
   select distinct r.investigation_id from mip_hypothesis.revisions r
   join mip_hypothesis.acceptance_bindings b on b.revision_id=r.id
   join evidence_pipeline.investigation_observations o on o.id=b.observation_id
   where not exists(select 1 from mip_hypothesis.revisions newer where newer.investigation_id=r.investigation_id and newer.revision>r.revision)
    and exists(select 1 from jsonb_array_elements(o.snapshot->'assessments') a where a->>'candidate_id'=new.candidate_id::text)
  loop perform mip_hypothesis.discover_reassessment_causes(iid);end loop;
 elsif tg_table_schema='evidence_pipeline' and tg_table_name='investigations' then
  if old.current_version_id is distinct from new.current_version_id then
   perform mip_hypothesis.discover_reassessment_causes(new.id);
  end if;
 elsif tg_table_schema='mip_identity' and tg_table_name='operation_evidence_heads' then
  for scope in select distinct v from (values
   (case when tg_op<>'INSERT' then old.scope end),
   (case when tg_op<>'DELETE' then new.scope end)) changed(v) where v is not null loop
  for iid in
   select distinct r.investigation_id from mip_hypothesis.revisions r
   join mip_hypothesis.acceptance_bindings b on b.revision_id=r.id
   where b.source_project=scope->>'source_project'
    and not exists(select 1 from mip_hypothesis.revisions newer where newer.investigation_id=r.investigation_id and newer.revision>r.revision)
    and exists(select 1 from jsonb_array_elements(b.metadata) e
     where e->>'material_hash'=scope->>'material_version' and e->>'material_version'=scope->>'source_version')
  loop perform mip_hypothesis.discover_reassessment_causes(iid);end loop;
  end loop;
 end if;
 return null;
end $$;

create function mip_hypothesis.reassessment_backlog(p_user uuid,p_investigation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare access text; entries jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 if not found then raise exception using errcode='55000',message='hypothesis fence unavailable';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-workspace-access:'||p_investigation::text||':'||p_user::text,0));
 select access_role into access from evidence_pipeline.investigation_memberships where investigation_id=p_investigation and user_id=p_user;
 if access is null or access not in('viewer','reviewer') then raise exception using errcode='42501',message='hypothesis backlog denied';end if;
 select coalesce(jsonb_agg(jsonb_build_object('cause_id',id,'revision_id',revision_id,'kind',kind,
  'change_position',change_position::text,'related_version_id',related_version_id,'detail',detail,'recorded_at',recorded_at,
  'state','pending_explicit_reconciliation') order by recorded_at,id),'[]'::jsonb) into entries
 from mip_hypothesis.reassessment_causes where investigation_id=p_investigation;
 return jsonb_build_object('contract_version','mip_hypothesis_reassessment_backlog_v1','investigation_id',p_investigation,
  'causes',entries,'coverage','retained_causes_only','completed_reassessment',false,'publication_allowed',false);
end $$;
create function mip_hypothesis.reconcile_reassessment_causes(p_user uuid,p_investigation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare access text;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 if not found then raise exception using errcode='55000',message='hypothesis fence unavailable';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-workspace-access:'||p_investigation::text||':'||p_user::text,0));
 select access_role into access from evidence_pipeline.investigation_memberships where investigation_id=p_investigation and user_id=p_user;
 if access is distinct from 'reviewer' then raise exception using errcode='42501',message='hypothesis reconciliation denied';end if;
 perform mip_hypothesis.discover_reassessment_causes(p_investigation);
 return mip_hypothesis.reassessment_backlog(p_user,p_investigation)||
  jsonb_build_object('coverage','current_head_watch_scope_at_reconciliation','completed_reassessment',false);
end $$;
revoke all on all functions in schema mip_hypothesis from public;
revoke all on mip_hypothesis.reassessment_causes from public;
grant execute on function mip_hypothesis.reassessment_backlog(uuid,uuid),
 mip_hypothesis.reconcile_reassessment_causes(uuid,uuid) to mip_hypothesis_gateway;
reset role;
create trigger hypothesis_reassessment_source after insert on evidence_pipeline.evidence_changes
 for each row execute function mip_hypothesis.reassessment_change_trigger();
create trigger hypothesis_reassessment_workspace after update on evidence_pipeline.investigations
 for each row execute function mip_hypothesis.reassessment_change_trigger();
create trigger hypothesis_reassessment_permission after insert or update or delete on mip_identity.operation_evidence_heads
 for each row execute function mip_hypothesis.reassessment_change_trigger();

create trigger hypothesis_assessment_fence before insert or update or delete or truncate on evidence_pipeline.assessments
 for each statement execute function mip_hypothesis.source_change_fence();
create trigger hypothesis_reassessment_assessment after insert on evidence_pipeline.assessments
 for each row execute function mip_hypothesis.reassessment_change_trigger();

-- Isolated atomic reassessment completion; no worker, publication or production deployment.
set role mip_hypothesis_owner;
create table mip_hypothesis.reassessment_completion_receipts(
 investigation_id uuid not null,
 request_id uuid not null,
 revision_id uuid not null unique,
 cause_ids uuid[] not null check(cardinality(cause_ids)>0),
 closure_bindings jsonb not null check(jsonb_typeof(closure_bindings)='array'),
 recorded_at timestamptz not null default clock_timestamp(),
 primary key(investigation_id,request_id),
 foreign key(investigation_id,revision_id) references mip_hypothesis.revisions(investigation_id,id)
);
create table mip_hypothesis.reassessment_resolutions(
 cause_id uuid primary key references mip_hypothesis.reassessment_causes(id),
 investigation_id uuid not null,
 completion_revision_id uuid not null,
 resolved_by uuid not null,
 recorded_at timestamptz not null default clock_timestamp(),
 foreign key(investigation_id,completion_revision_id) references mip_hypothesis.revisions(investigation_id,id)
);
create index reassessment_resolutions_revision on mip_hypothesis.reassessment_resolutions(investigation_id,completion_revision_id);
alter table mip_hypothesis.reassessment_completion_receipts enable row level security;
alter table mip_hypothesis.reassessment_completion_receipts force row level security;
alter table mip_hypothesis.reassessment_resolutions enable row level security;
alter table mip_hypothesis.reassessment_resolutions force row level security;
create policy owner_only on mip_hypothesis.reassessment_completion_receipts to mip_hypothesis_owner using(true) with check(true);
create policy owner_only on mip_hypothesis.reassessment_resolutions to mip_hypothesis_owner using(true) with check(true);
create trigger immutable_rows before update or delete on mip_hypothesis.reassessment_completion_receipts
 for each row execute function mip_hypothesis.reject_mutation();
create trigger immutable_table before truncate on mip_hypothesis.reassessment_completion_receipts
 for each statement execute function mip_hypothesis.reject_mutation();
create trigger immutable_rows before update or delete on mip_hypothesis.reassessment_resolutions
 for each row execute function mip_hypothesis.reject_mutation();
create trigger immutable_table before truncate on mip_hypothesis.reassessment_resolutions
 for each statement execute function mip_hypothesis.reject_mutation();

-- The prior acceptance kernel remains available only to the NOLOGIN owner.
alter function mip_hypothesis.append_bound_revision(uuid,uuid,uuid,text,uuid,uuid,jsonb) rename to append_bound_revision_v1;
revoke execute on function mip_hypothesis.append_bound_revision_v1(uuid,uuid,uuid,text,uuid,uuid,jsonb) from mip_hypothesis_gateway;
create function mip_hypothesis.append_bound_revision(p_user uuid,p_investigation uuid,p_version uuid,p_source_project text,
 p_request uuid,p_predecessor uuid,p_assessment jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare b jsonb; head uuid;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 if not found then raise exception using errcode='55000',message='hypothesis fence unavailable';end if;
 b:=mip_hypothesis.observation_binding(p_user,p_investigation,p_version);
 if b->>'access_role' is distinct from 'reviewer' then raise exception using errcode='42501',message='hypothesis append denied';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-hypothesis-question:'||p_investigation::text,0));
 if p_assessment ? 'reassessment_causes' then raise exception using errcode='22023',message='explicit reassessment completion required';end if;
 if not exists(select 1 from mip_hypothesis.revisions where investigation_id=p_investigation and request_id=p_request) then
  select id into head from mip_hypothesis.revisions where investigation_id=p_investigation order by revision desc limit 1;
  if head is distinct from p_predecessor then raise exception using errcode='40001',message='hypothesis predecessor changed';end if;
  perform mip_hypothesis.discover_reassessment_causes(p_investigation);
  if head is not null or exists(select 1 from mip_hypothesis.reassessment_causes c where c.investigation_id=p_investigation
    and not exists(select 1 from mip_hypothesis.reassessment_resolutions x where x.cause_id=c.id)) then
   raise exception using errcode='40001',message='hypothesis context changed; explicit reassessment completion required';
  end if;
 end if;
 return mip_hypothesis.append_bound_revision_v1(p_user,p_investigation,p_version,p_source_project,p_request,p_predecessor,p_assessment);
end $$;

create function mip_hypothesis.require_observed_operations(p_user uuid,p_investigation uuid,p_version uuid,
 p_source_project text,p_position text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare operation text; domain text; checked jsonb; receipts jsonb:='[]';
begin
 foreach operation in array array['retention','analysis','excerpt_display'] loop
 foreach domain in array array['rights','privacy'] loop
  checked:=mip_hypothesis.operation_permission(p_user,p_investigation,p_version,p_position,p_source_project,operation,domain);
  if checked->'allowed' is distinct from 'true'::jsonb or (
   (checked->'synthetic'='true'::jsonb and checked->>'reason'='synthetic_mechanism_only') or
   (checked->'synthetic'='false'::jsonb and checked->>'reason'='real_evidence_bound'
    and nullif(checked->>'admission_revision','') is not null
    and checked->>'material_hash'=checked->'scope'->>'material_version'
    and jsonb_typeof(checked->'primary_evidence_refs')='array' and jsonb_array_length(checked->'primary_evidence_refs')>0)
  ) is distinct from true then raise exception using errcode='42501',message='hypothesis operation denied';end if;
  receipts:=receipts||jsonb_build_array(jsonb_build_object('operation',operation,'domain',domain,
    'revision',checked->'revision','admission_revision',checked->'admission_revision','scope',checked->'scope'));
 end loop;end loop;
 return receipts;
end $$;

create function mip_hypothesis.validate_reassessment_closure(p_user uuid,p_investigation uuid,p_version uuid,
 p_source_project text,p_causes uuid[]) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v evidence_pipeline.investigation_versions; o evidence_pipeline.investigation_observations;
 c mip_hypothesis.reassessment_causes; b mip_hypothesis.acceptance_bindings; e jsonb; prior jsonb; checked jsonb; receipts jsonb; bindings jsonb:='[]';
begin
 select * into strict v from evidence_pipeline.investigation_versions where id=p_version and investigation_id=p_investigation;
 select * into strict o from evidence_pipeline.investigation_observations where id=v.observation_id;
 -- Reassessment considers the retained observation/dependency closure, not a caller-selected rights subset.
 for e in select value from jsonb_array_elements(o.snapshot->'inputs') loop
  receipts:=mip_hypothesis.require_observed_operations(p_user,p_investigation,p_version,p_source_project,e->>'position');
  bindings:=bindings||jsonb_build_array(jsonb_build_object('workspace_version_id',p_version,'input_position',e->>'position','permissions',receipts));
 end loop;
 for c in select * from mip_hypothesis.reassessment_causes where id=any(p_causes) order by case kind when 'retained_source_change' then 0 when 'retained_assessment_change' then 1 when 'workspace_changed' then 2 else 3 end,id loop
  if c.investigation_id<>p_investigation then raise exception using errcode='42501',message='reassessment cause scope denied';end if;
  select * into strict b from mip_hypothesis.acceptance_bindings where revision_id=c.revision_id;
  if b.source_project is distinct from p_source_project then raise exception using errcode='42501',message='reassessment source scope denied';end if;
  -- Preserve the complete prior completion closure even when the workspace scope narrows.
  for prior in select x.value from mip_hypothesis.reassessment_completion_receipts r
   cross join lateral jsonb_array_elements(r.closure_bindings) x where r.revision_id=c.revision_id loop
   receipts:=mip_hypothesis.require_observed_operations(p_user,p_investigation,
    (prior->>'workspace_version_id')::uuid,p_source_project,prior->>'input_position');
   bindings:=bindings||jsonb_build_array(jsonb_build_object('workspace_version_id',prior->>'workspace_version_id',
    'input_position',prior->>'input_position','permissions',receipts));
  end loop;
  -- Current authority over previously used material is required; old acceptance is not continuing permission.
  for e in select value from jsonb_array_elements(b.metadata) loop
   receipts:=mip_hypothesis.require_observed_operations(p_user,p_investigation,b.workspace_version_id,p_source_project,e->>'input_position');
   bindings:=bindings||jsonb_build_array(jsonb_build_object('workspace_version_id',b.workspace_version_id,'input_position',e->>'input_position','permissions',receipts));
  end loop;
  if c.kind='retained_source_change' and not exists(
   select 1 from jsonb_array_elements(o.snapshot->'inputs') i where i->>'position'=c.change_position::text) then
   raise exception using errcode='22023',message='reassessment missing retained source change';
  elsif c.kind='retained_assessment_change' and not exists(
   select 1 from jsonb_array_elements(o.snapshot->'assessments') a where a->>'id'=c.related_version_id::text) then
   raise exception using errcode='22023',message='reassessment missing retained assessment revision';
  elsif c.kind='workspace_changed' and not exists(
   with recursive lineage(id,predecessor_id) as (
    select id,predecessor_id from evidence_pipeline.investigation_versions where id=p_version and investigation_id=p_investigation
    union all select a.id,a.predecessor_id from evidence_pipeline.investigation_versions a join lineage l on a.id=l.predecessor_id
   ) select 1 from lineage where id=c.related_version_id
  ) then raise exception using errcode='22023',message='reassessment workspace lineage mismatch';
  elsif c.kind='permission_changed' then
   receipts:=mip_hypothesis.require_observed_operations(p_user,p_investigation,coalesce((c.detail->>'bound_workspace_version')::uuid,b.workspace_version_id),p_source_project,c.detail->>'input_position');
   select value into strict checked from jsonb_array_elements(receipts) p
    where p->>'operation'=c.detail->>'operation' and p->>'domain'=c.detail->>'domain';
   if checked->'revision' is not distinct from c.detail->'accepted_permission_revision' then
    raise exception using errcode='42501',message='fresh internal permission authorization required';
   end if;
  end if;
 end loop;
 -- Canonical unique bindings keep exact retries stable without multiplying inherited references.
 select coalesce(jsonb_agg(unique_bindings.v order by unique_bindings.v::text),'[]'::jsonb) into bindings
  from (select distinct value v from jsonb_array_elements(bindings)) unique_bindings;
 return bindings;
end $$;

create function mip_hypothesis.complete_reassessment(p_user uuid,p_investigation uuid,p_version uuid,p_source_project text,
 p_request uuid,p_predecessor uuid,p_assessment jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare b jsonb; annotation jsonb; supplied uuid[]; expected uuid[]; result jsonb; closure jsonb; receipt mip_hypothesis.reassessment_completion_receipts;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 if p_request is null or p_predecessor is null then raise exception using errcode='22023',message='reassessment identity required';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 if not found then raise exception using errcode='55000',message='hypothesis fence unavailable';end if;
 b:=mip_hypothesis.observation_binding(p_user,p_investigation,p_version);
 if b->>'access_role' is distinct from 'reviewer' then raise exception using errcode='42501',message='hypothesis completion denied';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-hypothesis-question:'||p_investigation::text,0));
 if jsonb_typeof(p_assessment->'reassessment_causes') is distinct from 'array' or jsonb_array_length(p_assessment->'reassessment_causes')=0 then
  raise exception using errcode='22023',message='explicit reassessment cause explanations required';end if;
 for annotation in select value from jsonb_array_elements(p_assessment->'reassessment_causes') loop
  if jsonb_typeof(annotation) is distinct from 'object' or not annotation ?& array['cause_id','reason']
    or exists(select 1 from jsonb_object_keys(annotation) k where k not in('cause_id','reason'))
    or nullif(btrim(annotation->>'reason'),'') is null then
   raise exception using errcode='22023',message='invalid reassessment cause explanation';end if;
 end loop;
 select array_agg((a->>'cause_id')::uuid order by (a->>'cause_id')::uuid) into supplied
  from jsonb_array_elements(p_assessment->'reassessment_causes') a;
 if array_position(supplied,null) is not null or cardinality(supplied)<>(select count(distinct x) from unnest(supplied) x) then
  raise exception using errcode='22023',message='ambiguous reassessment causes';end if;
 select * into receipt from mip_hypothesis.reassessment_completion_receipts where investigation_id=p_investigation and request_id=p_request;
 if found then
  if supplied is distinct from receipt.cause_ids then raise exception using errcode='23505',message='reassessment retry conflict';end if;
 else
  if exists(select 1 from mip_hypothesis.revisions where investigation_id=p_investigation and request_id=p_request) then
   raise exception using errcode='23505',message='reassessment request already used';end if;
  perform mip_hypothesis.discover_reassessment_causes(p_investigation);
  select array_agg(c.id order by c.id) into expected from mip_hypothesis.reassessment_causes c
   where c.investigation_id=p_investigation and not exists(select 1 from mip_hypothesis.reassessment_resolutions x where x.cause_id=c.id);
  if expected is null or supplied is distinct from expected then
   raise exception using errcode='40001',message='reassessment pending cause set changed';end if;
 end if;
 closure:=mip_hypothesis.validate_reassessment_closure(p_user,p_investigation,p_version,p_source_project,supplied);
 if receipt.request_id is not null and closure is distinct from receipt.closure_bindings then
  raise exception using errcode='42501',message='fresh bound reassessment required';end if;
 -- Kernel rechecks current context/permissions and exact owner/arguments for receipt replay.
 result:=mip_hypothesis.append_bound_revision_v1(p_user,p_investigation,p_version,p_source_project,p_request,p_predecessor,p_assessment);
 if receipt.request_id is null then
  insert into mip_hypothesis.reassessment_completion_receipts(investigation_id,request_id,revision_id,cause_ids,closure_bindings)
   values(p_investigation,p_request,(result->'assessment'->>'id')::uuid,supplied,closure) returning * into receipt;
  insert into mip_hypothesis.reassessment_resolutions(cause_id,investigation_id,completion_revision_id,resolved_by)
   select x,p_investigation,receipt.revision_id,p_user from unnest(supplied) x;
 end if;
 return result||jsonb_build_object('completed_reassessment',true,'completion_receipt',
  jsonb_build_object('request_id',receipt.request_id,'revision_id',receipt.revision_id,'cause_ids',receipt.cause_ids),
  'reassessment_pending',(result->'reassessment_pending'='true'::jsonb) or exists(
   select 1 from mip_hypothesis.reassessment_causes c where c.investigation_id=p_investigation
    and not exists(select 1 from mip_hypothesis.reassessment_resolutions x where x.cause_id=c.id)));
end $$;

alter function mip_hypothesis.reassessment_backlog(uuid,uuid) rename to reassessment_backlog_v1;
revoke execute on function mip_hypothesis.reassessment_backlog_v1(uuid,uuid) from mip_hypothesis_gateway;
create function mip_hypothesis.reassessment_backlog(p_user uuid,p_investigation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb; causes jsonb;
begin
 result:=mip_hypothesis.reassessment_backlog_v1(p_user,p_investigation);
 select coalesce(jsonb_agg(c||case when x.cause_id is null then '{}'::jsonb else jsonb_build_object(
   'state','reassessment_recorded','resolution_revision_id',x.completion_revision_id,'resolved_at',x.recorded_at) end
   order by c->>'recorded_at',c->>'cause_id'),'[]'::jsonb) into causes
 from jsonb_array_elements(result->'causes') c left join mip_hypothesis.reassessment_resolutions x on x.cause_id=(c->>'cause_id')::uuid;
 return result||jsonb_build_object('contract_version','mip_hypothesis_reassessment_backlog_v2','causes',causes,'is_completion_receipt',false);
end $$;

-- Extend current-head discovery to every permission that the completion actually depended on.
alter function mip_hypothesis.discover_reassessment_causes(uuid) rename to discover_reassessment_causes_v1;
create function mip_hypothesis.discover_reassessment_causes(p_investigation uuid) returns void
language plpgsql security definer set search_path='' as $$
declare r mip_hypothesis.revisions; receipt mip_hypothesis.reassessment_completion_receipts; b jsonb; p jsonb; checked jsonb; reason text; key text;
begin
 perform mip_hypothesis.discover_reassessment_causes_v1(p_investigation);
 select * into r from mip_hypothesis.revisions where investigation_id=p_investigation order by revision desc limit 1;
 if not found then return;end if;
 select * into receipt from mip_hypothesis.reassessment_completion_receipts where revision_id=r.id;
 if not found then return;end if;
 for b in select value from jsonb_array_elements(receipt.closure_bindings) loop
 for p in select value from jsonb_array_elements(b->'permissions') loop
  checked:=mip_identity.operation_check(p->'scope');
  reason:=case when checked->'allowed' is distinct from 'true'::jsonb then 'current_permission_denied'
   when checked->'revision' is distinct from p->'revision' or
    coalesce(checked->'admission_revision','null'::jsonb) is distinct from coalesce(p->'admission_revision','null'::jsonb)
   then 'permission_binding_changed' else null end;
  if reason is not null then
   key:='permission:'||encode(sha256(convert_to((p->'scope')::text,'UTF8')),'hex')||':'||coalesce(checked->>'revision','missing')||':'||reason;
   insert into mip_hypothesis.reassessment_causes(investigation_id,revision_id,cause_key,kind,detail)
   values(p_investigation,r.id,key,'permission_changed',jsonb_build_object('input_position',b->>'input_position',
    'bound_workspace_version',b->>'workspace_version_id','operation',p->>'operation','domain',p->>'domain',
    'accepted_permission_revision',p->'revision','observed_permission_revision',checked->'revision','reason',reason))
   on conflict(revision_id,cause_key) do nothing;
  end if;
 end loop;end loop;
end $$;
create function mip_hypothesis.completion_permission_change_trigger() returns trigger
language plpgsql security definer set search_path='' as $$
declare scope jsonb; iid uuid;
begin
 for scope in select distinct v from (values
  (case when tg_op<>'INSERT' then old.scope end),(case when tg_op<>'DELETE' then new.scope end)) changed(v) where v is not null loop
  for iid in select distinct r.investigation_id from mip_hypothesis.revisions r
   join mip_hypothesis.reassessment_completion_receipts c on c.revision_id=r.id
   where not exists(select 1 from mip_hypothesis.revisions n where n.investigation_id=r.investigation_id and n.revision>r.revision)
    and exists(select 1 from jsonb_array_elements(c.closure_bindings) b
      cross join lateral jsonb_array_elements(b->'permissions') p where p->'scope'=scope)
  loop perform mip_hypothesis.discover_reassessment_causes(iid);end loop;
 end loop;
 return null;
end $$;
-- A restored permission cannot reveal an old completed payload as if a fresh assessment occurred.
alter function mip_hypothesis.read_bound_history(uuid,uuid) rename to read_bound_history_v1;
revoke execute on function mip_hypothesis.read_bound_history_v1(uuid,uuid) from mip_hypothesis_gateway;
create function mip_hypothesis.read_bound_history(p_user uuid,p_investigation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb; entries jsonb:='[]'; e jsonb; receipt mip_hypothesis.reassessment_completion_receipts;
 b mip_hypothesis.acceptance_bindings; current_bindings jsonb; allowed boolean;
begin
 result:=mip_hypothesis.read_bound_history_v1(p_user,p_investigation);
 for e in select value from jsonb_array_elements(result->'entries') loop
  select * into receipt from mip_hypothesis.reassessment_completion_receipts where revision_id=(e->>'revision_id')::uuid;
  if found and e->>'status'='available' then
   select * into strict b from mip_hypothesis.acceptance_bindings where revision_id=receipt.revision_id;
   allowed:=true;
   begin
    current_bindings:=mip_hypothesis.validate_reassessment_closure(p_user,p_investigation,b.workspace_version_id,b.source_project,receipt.cause_ids);
    allowed:=current_bindings=receipt.closure_bindings;
   exception when insufficient_privilege or invalid_parameter_value or no_data_found then allowed:=false;
   end;
   if not allowed then e:=(e-'assessment'-'current_context'-'reassessment_pending')||
     jsonb_build_object('status','withheld','reason','permission_binding_changed_fresh_review_required');end if;
  end if;
  entries:=entries||jsonb_build_array(e);
 end loop;
 return result||jsonb_build_object('entries',entries);
end $$;

