alter schema comparison_qualification owner to mip_cutover_schema_owner_v1;
alter schema mip_cutover_authority owner to mip_cutover_schema_owner_v1;
-- Remove the old direct entrypoints from the intended external worker boundary.
revoke execute on function mip_cutover_authority.worker_claim(uuid,uuid,text),
 mip_cutover_authority.worker_complete(uuid,uuid,text,uuid,uuid,text,text,jsonb),
 mip_cutover_authority.worker_fail(uuid,uuid,text,uuid,uuid,text,text) from mip_comparison_worker_v1;
revoke execute on function mip_cutover_authority.producer_enqueue(uuid,uuid,text,jsonb,timestamptz) from mip_comparison_producer_v1;
commit;

-- Isolated collector/backlog/delta integration. No live collector or schedule changes.
begin;
do $$begin if not exists(select 1 from pg_roles where rolname='mip_collector_owner_v2') then
 create role mip_collector_owner_v2 nologin nosuperuser nobypassrls;end if;end $$;
create table mip_identity.collector_config(id boolean primary key check(id),source text not null);
create table mip_identity.collector_fence(id boolean primary key check(id));
insert into mip_identity.collector_fence values(true);
create table mip_identity.source_changes(
 id uuid primary key default gen_random_uuid(),source text not null,relation_name text not null,
 row_key text not null,before_row jsonb,after_row jsonb,kind text not null check(kind in ('backlog','delta')),
 transaction_id text not null,retained_at timestamptz not null default clock_timestamp()
);
create table mip_identity.generation_changes(
 change_id uuid primary key references mip_identity.source_changes,
 generation_id uuid not null references comparison_qualification.generations
);
create table mip_identity.collector_runs(
 request_id uuid primary key,runtime text not null,generation_id uuid references comparison_qualification.generations
);
create function mip_identity.collector_lock() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 perform 1 from mip_identity.collector_fence where id for update;return null;
end $$;
create function mip_identity.collector_change() returns trigger
language plpgsql security definer set search_path='' as $$
declare src text;b jsonb;a jsonb;k text;
begin
 select source into strict src from mip_identity.collector_config where id;
 b:=case when tg_op='INSERT' then null else to_jsonb(old) end;
 a:=case when tg_op='DELETE' then null else to_jsonb(new) end;
 if a is not distinct from b then return null;end if;
 k:=coalesce(a,b)->>tg_argv[0];
 if tg_nargs>1 then k:=k||':'||(coalesce(a,b)->>tg_argv[1]);end if;
 -- Composite/unknown topology keys retain exact before/after content even without id.
 if k is null then k:=encode(sha256(convert_to(coalesce(a,b)::text,'UTF8')),'hex');end if;
 insert into mip_identity.source_changes(source,relation_name,row_key,before_row,after_row,kind,transaction_id)
 values(src,tg_table_schema||'.'||tg_table_name,k,b,a,'delta',pg_current_xact_id()::text);
 return null;
end $$;
create trigger collector_events_lock before insert or update or delete or truncate on public.events for each statement execute function mip_identity.collector_lock();
create trigger collector_events_change after insert or update or delete on public.events for each row execute function mip_identity.collector_change('id');
create trigger collector_articles_lock before insert or update or delete or truncate on public.articles for each statement execute function mip_identity.collector_lock();
create trigger collector_articles_change after insert or update or delete on public.articles for each row execute function mip_identity.collector_change('id');
create trigger collector_membership_lock before insert or update or delete or truncate on public.event_articles for each statement execute function mip_identity.collector_lock();
create trigger collector_membership_change after insert or update or delete on public.event_articles for each row execute function mip_identity.collector_change('event_id','article_id');
create trigger collector_config_lock before insert or update or delete or truncate on public.pipeline_config for each statement execute function mip_identity.collector_lock();
create trigger collector_config_change after insert or update or delete on public.pipeline_config for each row execute function mip_identity.collector_change('key');
-- TRUNCATE cannot supply per-row retained evidence: reject instead of losing history.
create trigger no_collector_events_truncate before truncate on public.events for each statement execute function comparison_qualification.reject_rewrite();
create trigger no_collector_articles_truncate before truncate on public.articles for each statement execute function comparison_qualification.reject_rewrite();
create trigger no_collector_membership_truncate before truncate on public.event_articles for each statement execute function comparison_qualification.reject_rewrite();
create trigger no_collector_config_truncate before truncate on public.pipeline_config for each statement execute function comparison_qualification.reject_rewrite();
create function mip_identity.capture_backlog() returns integer
language plpgsql security definer set search_path='' as $$
declare src text;n integer;
begin
 perform 1 from mip_identity.collector_fence where id for update;
 select source into strict src from mip_identity.collector_config where id;
 if exists(select 1 from mip_identity.source_changes where source=src) then raise exception 'mip_backlog_already_started';end if;
 insert into mip_identity.source_changes(source,relation_name,row_key,before_row,after_row,kind,transaction_id)
 select src,relation_name,row_key,null,payload,'backlog',pg_current_xact_id()::text from (
 select 'public.events' relation_name,id::text row_key,to_jsonb(e) payload from public.events e
 union all select 'public.articles',id::text,to_jsonb(a) from public.articles a
 union all select 'public.event_articles',event_id::text||':'||article_id::text,to_jsonb(m) from public.event_articles m
 union all select 'public.pipeline_config',key,to_jsonb(c) from public.pipeline_config c
 ) rows;
 get diagnostics n=row_count;return n;
end $$;
create function mip_identity.capture_delta(p_request uuid,p_session uuid,p_runtime text) returns uuid
language plpgsql security definer set search_path='' as $$
declare prior mip_identity.collector_runs;g uuid;src text;
begin
 perform mip_identity.authorize(p_session,p_runtime,'mip_comparison_producer_v1');
 perform 1 from mip_identity.collector_fence where id for update;
 select source into strict src from mip_identity.collector_config where id;
 perform comparison_qualification.require_source_scope(p_runtime,src);
 select * into prior from mip_identity.collector_runs where request_id=p_request;
 if found then
 if prior.runtime is distinct from p_runtime then raise exception 'mip_collector_replay_owner';end if;
 return prior.generation_id;end if;
 select source into strict src from mip_identity.collector_config where id;
 perform comparison_qualification.require_source_scope(p_runtime,src);
 if exists(select 1 from mip_identity.source_changes c where c.source=src and not exists(select 1 from mip_identity.generation_changes g where g.change_id=c.id)) then
 g:=mip_identity.producer_enqueue(p_request,p_session,p_runtime,'{}',null);
 if not exists(select 1 from comparison_qualification.generations where id=g and source_project=src) then raise exception 'mip_collector_source_mismatch';end if;
 insert into mip_identity.generation_changes
 select c.id,g from mip_identity.source_changes c where c.source=src
 and not exists(select 1 from mip_identity.generation_changes x where x.change_id=c.id);
 end if;
 insert into mip_identity.collector_runs values(p_request,p_runtime,g);
 perform mip_identity.authorize(p_session,p_runtime,'mip_comparison_producer_v1');
 return g;
end $$;
create function mip_identity.reconciliation(p_session uuid,p_runtime text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare src text;result jsonb;
begin
 perform mip_identity.authorize(p_session,p_runtime,'mip_comparison_producer_v1');
 select source into strict src from mip_identity.collector_config where id;
 perform comparison_qualification.require_source_scope(p_runtime,src);
 select coalesce(jsonb_agg(jsonb_build_object('change_id',c.id,'relation',c.relation_name,'row_key',c.row_key,
 'kind',c.kind,'before_hash',case when c.before_row is null then null else comparison_qualification.argument_digest(c.before_row) end,
 'after_hash',case when c.after_row is null then null else comparison_qualification.argument_digest(c.after_row) end,
 'generation_id',g.id,'input_hash',g.input_hash,'output_hash',o.output_hash,
 'job_state',j.state,'acknowledged',coalesce(j.state='completed' and o.generation_id=g.id,false))
 order by c.retained_at,c.id),'[]') into result
 from mip_identity.source_changes c left join mip_identity.generation_changes x on x.change_id=c.id
 left join comparison_qualification.generations g on g.id=x.generation_id
 left join comparison_qualification.jobs j on j.generation_id=g.id
 left join comparison_qualification.outputs o on o.generation_id=g.id where c.source=src;
 perform mip_identity.authorize(p_session,p_runtime,'mip_comparison_producer_v1');
 return result;
end $$;
do $permissions$
declare t text;r record;
begin
 foreach t in array array['collector_config','collector_fence','source_changes','generation_changes','collector_runs'] loop
 execute format('alter table mip_identity.%I owner to mip_cutover_schema_owner_v1',t);
 execute format('alter table mip_identity.%I enable row level security',t);
 execute format('alter table mip_identity.%I force row level security',t);
 execute format('revoke all on mip_identity.%I from public,anon,authenticated,service_role',t);
 execute format('grant select on mip_identity.%I to mip_collector_owner_v2',t);
 execute format('create policy collector_read on mip_identity.%I for select to mip_collector_owner_v2 using(true)',t);
 end loop;
 foreach t in array array['source_changes','generation_changes','collector_runs'] loop
 execute format('grant insert on mip_identity.%I to mip_collector_owner_v2',t);
 execute format('create policy collector_append on mip_identity.%I for insert to mip_collector_owner_v2 with check(true)',t);
 execute format('create trigger immutable before update or delete on mip_identity.%I for each row execute function comparison_qualification.reject_rewrite()',t);
 execute format('create trigger no_truncate before truncate on mip_identity.%I for each statement execute function comparison_qualification.reject_rewrite()',t);
 end loop;
 for r in select p.oid::regprocedure::text sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='mip_identity' and p.proname in ('collector_lock','collector_change','capture_backlog','capture_delta','reconciliation') loop
 execute 'alter function '||r.sig||' owner to mip_collector_owner_v2';
 execute 'revoke all on function '||r.sig||' from public,anon,authenticated,service_role';
 end loop;
end $permissions$;
grant usage on schema mip_identity,comparison_qualification,public to mip_collector_owner_v2;
grant select on public.events,public.articles,public.event_articles,public.pipeline_config to mip_collector_owner_v2;
grant select on comparison_qualification.generations,comparison_qualification.jobs,comparison_qualification.outputs to mip_collector_owner_v2;
create policy collector_generation_read on comparison_qualification.generations for select to mip_collector_owner_v2 using(true);
create policy collector_job_read on comparison_qualification.jobs for select to mip_collector_owner_v2 using(true);
create policy collector_output_read on comparison_qualification.outputs for select to mip_collector_owner_v2 using(true);
grant update on mip_identity.collector_fence to mip_collector_owner_v2;
create policy collector_fence_lock on mip_identity.collector_fence for update to mip_collector_owner_v2 using(true) with check(true);
grant execute on function mip_identity.authorize(uuid,text,text),mip_identity.producer_enqueue(uuid,uuid,text,jsonb,timestamptz),
 comparison_qualification.require_source_scope(text,text),comparison_qualification.argument_digest(jsonb) to mip_collector_owner_v2;
grant execute on function mip_identity.capture_delta(uuid,uuid,text),mip_identity.reconciliation(uuid,text) to mip_comparison_producer_v1;
-- capture_backlog is an explicit trusted bootstrap operation; no worker grant.
commit;

-- Isolated retained-evidence adapter and private release path. Actual public release stays disabled.
begin;
do $$begin if not exists(select 1 from pg_roles where rolname='mip_publication_owner_v2') then
 create role mip_publication_owner_v2 nologin nosuperuser nobypassrls;end if;end $$;
alter table mip_identity.mapping_versions drop constraint mapping_versions_principal_check;
alter table mip_identity.mapping_versions add check(principal in ('mip_comparison_worker_v1','mip_comparison_producer_v1','mip_projection_publisher_v1'));
create table mip_identity.publication_policy_versions(
 revision uuid primary key,privacy_rule_ref text not null check(length(privacy_rule_ref)>0),
 rights_rule_ref text not null check(length(rights_rule_ref)>0),
 publication_rule_ref text not null check(length(publication_rule_ref)>0),
 adapter_ref text not null check(adapter_ref='survivor-reader-v1'),
 approval_ref text not null check(length(approval_ref)>0)
);
create table mip_identity.publication_policy_heads(
 id boolean primary key check(id),revision uuid not null references mip_identity.publication_policy_versions,active boolean not null
);
create trigger policy_fence before insert or update or delete or truncate on mip_identity.publication_policy_heads
 for each statement execute function mip_cutover_authority.fence_publication_write();
create trigger policy_retirement before insert or update or delete on mip_identity.publication_policy_heads
 for each row execute function mip_identity.guard_revision_reuse();
create table mip_identity.publication_reviews(
 revision uuid primary key,generation_id uuid not null references comparison_qualification.outputs(generation_id),
 input_hash text not null,output_hash text not null,
 policy_revision uuid not null references mip_identity.publication_policy_versions,
 privacy_status text not null check(privacy_status in ('eligible','ineligible','unknown')),
 rights_status text not null check(rights_status in ('eligible','ineligible','unknown')),
 evidence jsonb not null,explanations jsonb not null,relationship_context jsonb not null,
 valid_until timestamptz not null check(isfinite(valid_until)),policy_ref text not null check(length(policy_ref)>0),
 authorization_ref text not null check(length(authorization_ref)>0)
);
create table mip_identity.publication_review_heads(
 generation_id uuid primary key,revision uuid not null references mip_identity.publication_reviews,active boolean not null
);
create table mip_identity.review_stages(
 review_revision uuid primary key references mip_identity.publication_reviews,
 approved_payload_id uuid not null unique references mip_cutover_authority.approved_payloads
);
create table mip_identity.private_releases(
 request_id uuid primary key,runtime text not null,review_revision uuid not null,
 approved_payload_id uuid not null references mip_cutover_authority.approved_payloads,
 payload_hash text not null,recorded_at timestamptz not null default clock_timestamp()
);
create function mip_identity.survivor_relations() returns text[] language sql immutable set search_path='' as $$
 select array['events','articles','event_articles','pipeline_config','claims','article_claims',
 'claim_evidence_links','claim_corrections','explanations','story_arcs','nodes',
 'edges','arc_events','arc_milestones','arc_membership_candidates'];
$$;
create function mip_identity.survivor_context() returns jsonb
language plpgsql security definer set search_path='' as $$
declare name text;rows jsonb;result jsonb:='{}';
begin
 foreach name in array mip_identity.survivor_relations() loop
 if to_regclass('public.'||name) is null or not exists(
 select 1 from pg_trigger where tgrelid=to_regclass('public.'||name) and tgname='survivor_mutation_lock' and tgenabled='O')
 then raise exception 'mip_survivor_relation_or_fence_missing';end if;
 execute format('select coalesce(jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text),''[]''::jsonb) from public.%I r',name) into rows;
 result:=result||jsonb_build_object(name,rows);
 end loop;
 return result;
end $$;
-- Only explicit trusted installation can call this. No live migration invocation.
create function mip_identity.install_survivor_fences() returns void
language plpgsql security invoker set search_path='' as $$
declare name text;
begin
 foreach name in array mip_identity.survivor_relations() loop
 if to_regclass('public.'||name) is null then raise exception 'mip_survivor_relation_missing';end if;
 execute format('create trigger survivor_mutation_lock before insert or update or delete or truncate on public.%I for each statement execute function mip_identity.collector_lock()',name);
 if name not in ('events','articles','event_articles','pipeline_config') then
 execute format('create trigger survivor_retention after insert or update or delete on public.%I for each row execute function mip_identity.collector_change(''id'')',name);
 execute format('create trigger survivor_no_truncate before truncate on public.%I for each statement execute function comparison_qualification.reject_rewrite()',name);
 end if;
 execute format('grant select on public.%I to mip_publication_owner_v2',name);
 end loop;
end $$;
create function mip_identity.invalidate_source_publications() returns trigger
language plpgsql security definer set search_path='' as $$
declare dep mip_cutover_authority.dependency_versions;v uuid;
begin
 -- Collector's source fence is already held, then publication fence; consistent order.
 perform 1 from mip_cutover_authority.publication_fence where id for update;
 for dep in select d.* from mip_cutover_authority.dependency_heads h
 join mip_cutover_authority.dependency_versions d on d.id=h.version_id
 where d.source=new.source and d.state='current' order by h.dependency_key loop
 insert into mip_cutover_authority.dependency_versions(dependency_key,source,children,record_hash,
 privacy_eligible,rights_eligible,retained_evidence,correction_current,explanation_eligible,publication_eligible,
 state,valid_until,predicate_version)
 values(dep.dependency_key,dep.source,dep.children,dep.record_hash,false,false,dep.retained_evidence,
 false,false,false,'revoked',dep.valid_until,dep.predicate_version) returning id into v;
 update mip_cutover_authority.dependency_heads set version_id=v where dependency_key=dep.dependency_key;
 end loop;
 return null;
end $$;
create trigger invalidate_retained_change after insert on mip_identity.source_changes for each row execute function mip_identity.invalidate_source_publications();
create trigger publication_review_fence before insert or update or delete or truncate on mip_identity.publication_review_heads
 for each statement execute function mip_cutover_authority.fence_publication_write();
create trigger publication_review_retirement before insert or update or delete on mip_identity.publication_review_heads
 for each row execute function mip_identity.guard_revision_reuse();

create function mip_identity.validate_review(p_revision uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare rev mip_identity.publication_reviews;g comparison_qualification.generations;o comparison_qualification.outputs;pc jsonb;
 current_input jsonb;event_input jsonb;member jsonb;ac jsonb;ev jsonb;x jsonb;original jsonb;article jsonb;field text;valid boolean;links jsonb:='[]';corrections jsonb:='[]';target jsonb;relation jsonb;source_claim jsonb;
begin
 perform 1 from mip_identity.collector_fence where id for share;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 select r.* into rev from mip_identity.publication_reviews r join mip_identity.publication_review_heads h on h.revision=r.revision
 and h.generation_id=r.generation_id and h.active where r.revision=p_revision;
 if not found or rev.valid_until<=clock_timestamp() or rev.privacy_status<>'eligible' or rev.rights_status<>'eligible' then
 raise exception 'mip_publication_authority_missing';end if;
 if not exists(select 1 from mip_identity.publication_policy_heads h join mip_identity.publication_policy_versions v on v.revision=h.revision
 where h.id and h.active and h.revision=rev.policy_revision and v.adapter_ref='survivor-reader-v1') then raise exception 'mip_publication_policy_revoked';end if;
 select * into strict g from comparison_qualification.generations where id=rev.generation_id;
 select * into strict o from comparison_qualification.outputs where generation_id=g.id;
 if rev.input_hash is distinct from g.input_hash or rev.output_hash is distinct from o.output_hash then raise exception 'mip_publication_binding';end if;
 current_input:=comparison_qualification.source_snapshot(g.input_payload->'lexicon',g.implementation_ref);
 if (current_input-'snapshot_metadata') is distinct from (g.input_payload-'snapshot_metadata') then raise exception 'mip_publication_stale_source_input';end if;
 if mip_identity.survivor_context() is distinct from rev.relationship_context then raise exception 'mip_publication_stale_source_context';end if;
 if jsonb_typeof(g.input_payload->'eventInputs') is distinct from 'array'
 or jsonb_array_length(g.input_payload->'eventInputs')=0 then raise exception 'mip_publication_missing_input';end if;
 for event_input in select value from jsonb_array_elements(g.input_payload->'eventInputs') loop
 if event_input#>>'{event,comparison_validation_state}' is distinct from 'approved'
 or event_input#>>'{event,status}' is null or event_input#>>'{event,status}'='timeline_only'
 or (select count(distinct value#>>'{article,outlet}') from jsonb_array_elements(event_input->'members'))<2
 then raise exception 'mip_publication_event_ineligible';end if;
 for member in select value from jsonb_array_elements(event_input->'members') loop
 if member#>>'{article,reader_state}' is distinct from 'eligible'
 or member#>>'{article,source_status}' is distinct from 'active' then raise exception 'mip_publication_article_ineligible';end if;
 end loop;end loop;
 if jsonb_typeof(rev.evidence) is distinct from 'array' or jsonb_array_length(rev.evidence)=0
 or jsonb_typeof(rev.explanations) is distinct from 'array'
 or jsonb_typeof(o.output_payload#>'{projection,article_claims}') is distinct from 'array'
 or jsonb_array_length(o.output_payload#>'{projection,article_claims}')=0
 then raise exception 'mip_publication_evidence_missing';end if;
 if jsonb_typeof(o.output_payload#>'{projection,claims}') is distinct from 'array'
 or jsonb_typeof(o.output_payload#>'{projection,explanations}') is distinct from 'array'
 or jsonb_array_length(o.output_payload#>'{projection,explanations}')=0 then raise exception 'mip_publication_explanation_missing';end if;
 for pc in select value from jsonb_array_elements(o.output_payload#>'{projection,claims}') loop
 if pc->>'status' is distinct from 'active' or pc->>'rule_version' is distinct from 'sc-v2-event-projection'
 or not exists(select 1 from jsonb_array_elements(g.input_payload->'eventInputs') e where e.value#>>'{event,id}'=pc->>'event_id')
 then raise exception 'mip_publication_claim_ineligible';end if;
 end loop;
 for ac in select value from jsonb_array_elements(o.output_payload#>'{projection,article_claims}') loop
 valid:=false;
 if not exists(select 1 from jsonb_array_elements(o.output_payload#>'{projection,claims}') c
 join lateral jsonb_array_elements(g.input_payload->'eventInputs') e on e.value#>>'{event,id}'=c.value->>'event_id'
 cross join lateral jsonb_array_elements(e.value->'members') m
 where c.value->>'claim_key'=ac->>'claim_key' and m.value#>>'{article,id}'=ac->>'article_id')
 then raise exception 'mip_publication_membership_missing';end if;
 for ev in select value from jsonb_array_elements(rev.evidence) where value->>'article_id'=ac->>'article_id' and value->>'claim_key'=ac->>'claim_key' loop
 select m.value->'article' into article from jsonb_array_elements(g.input_payload->'eventInputs') e
 cross join lateral jsonb_array_elements(e.value->'members') m where m.value#>>'{article,id}'=ac->>'article_id' limit 1;
 field:=ev->>'field';
 if field in ('title','summary','body_text') and ev->>'auditability_state'='verified_retained_source'
 and nullif(ev->>'excerpt','') is not null and ev->>'excerpt'=ac->>'surface_text'
 and position((ev->>'excerpt') in coalesce(article->>field,''))>0
 and ev->>'field_hash'=encode(sha256(convert_to(article->>field,'UTF8')),'hex') then valid:=true;end if;
 end loop;
 if not valid then raise exception 'mip_publication_retained_evidence_missing';end if;
 end loop;
 if jsonb_array_length(rev.explanations)<>jsonb_array_length(o.output_payload#>'{projection,explanations}')
 or jsonb_array_length(rev.explanations)<>(select count(distinct value->>'assertion_id') from jsonb_array_elements(rev.explanations))
 then raise exception 'mip_publication_explanation_missing';end if;
 for x in select value from jsonb_array_elements(rev.explanations) loop
 select value into original from jsonb_array_elements(o.output_payload#>'{projection,explanations}') where value->>'assertion_id'=x->>'assertion_id';
 if not found or x->>'assertion_type' is distinct from 'claim_grouping' or x->>'rule_version' not like 'sc-v2-event-projection|%' or nullif(btrim(x->>'supporting_passage'),'') is null or x->>'review_status' is distinct from 'published' or x->>'state' is distinct from 'ok'
 or x->'is_current' is distinct from 'true'::jsonb or x->>'rule_version' is distinct from original->>'rule_version'
 or x->>'supporting_passage' is distinct from original->>'supporting_passage'
 or nullif(btrim(x->>'falsification_condition'),'') is null or btrim(x->>'falsification_condition') ilike 'missing:%'
 or jsonb_typeof(x->'archived_sources') is distinct from 'array' or jsonb_array_length(x->'archived_sources')=0
 then raise exception 'mip_publication_explanation_ineligible';end if;
 for ev in select value from jsonb_array_elements(x->'archived_sources') loop
 if ev->>'status' is distinct from 'retained' or not exists(select 1 from jsonb_array_elements(rev.evidence) e where e.value->>'field_hash'=ev->>'field_hash' and e.value->>'article_id'=ev->>'article_id')
 then raise exception 'mip_publication_archive_missing';end if;
 end loop;
 if not exists(select 1 from jsonb_array_elements(o.output_payload#>'{projection,claims}') c
 join lateral jsonb_array_elements(o.output_payload#>'{projection,article_claims}') a on a.value->>'claim_key'=c.value->>'claim_key'
 where x->>'assertion_id' ~ ('^sc:claim_grouping:'||(c.value->>'event_id')||':[0-9]+:'||(a.value->>'article_id')||'$')
 and position(format('Surface claim "%s" grouped under canonical "%s"',a.value->>'surface_text',c.value->>'canonical_text') in (x->>'supporting_passage'))=1
 and exists(select 1 from jsonb_array_elements(x->'archived_sources') z where z.value->>'article_id'=a.value->>'article_id'))
 then raise exception 'mip_publication_explanation_binding';end if;
 end loop;

 -- A fresh review cannot relabel an explicitly withdrawn/revoked dependency current.
 for relation in select value from jsonb_each(rev.relationship_context) loop
 for ev in select value from jsonb_array_elements(relation) loop
 if ev->>'state' in ('withdrawn','revoked') or ev->>'status' in ('withdrawn','revoked')
 or ev->'privacy_eligible'='false'::jsonb or ev->'rights_eligible'='false'::jsonb
 or (ev ? 'reader_state' and ev->>'reader_state' is distinct from 'eligible')
 or (ev ? 'source_status' and ev->>'source_status' is distinct from 'active')
 then raise exception 'mip_publication_dependency_ineligible';end if;
 end loop;end loop;
 -- Bind existing evidence links/corrections by exact event and canonical claim.
 -- Ambiguous/missing bindings fail closed; no worker attestation or URL synthesis.
 for relation in select value from jsonb_array_elements(rev.relationship_context->'claim_evidence_links') loop
 select value into source_claim from jsonb_array_elements(rev.relationship_context->'claims') where value->>'id'=relation->>'claim_id';
 select value into target from jsonb_array_elements(o.output_payload#>'{projection,claims}')
 where value->>'event_id'=source_claim->>'event_id' and value->>'canonical_text'=source_claim->>'canonical_text';
 if target is null or source_claim->>'status' is distinct from 'active' or source_claim->>'rule_version' is distinct from 'sc-v2-event-projection'
 or not exists(select 1 from jsonb_array_elements(rev.evidence) e where e.value->>'claim_key'=target->>'claim_key' and e.value->>'article_id'=relation->>'linked_from_article_id')
 or nullif(relation->>'evidence_url','') is null then raise exception 'mip_publication_link_ineligible';end if;
 links:=links||jsonb_build_array(relation||jsonb_build_object('claim_key',target->>'claim_key'));
 end loop;
 for relation in select value from jsonb_array_elements(rev.relationship_context->'claim_corrections') loop
 select value into source_claim from jsonb_array_elements(rev.relationship_context->'claims') where value->>'id'=relation->>'claim_id';
 select value into target from jsonb_array_elements(o.output_payload#>'{projection,claims}')
 where value->>'event_id'=source_claim->>'event_id' and value->>'canonical_text'=source_claim->>'canonical_text';
 if target is null or source_claim->>'status' is distinct from 'active'
 or not exists(select 1 from jsonb_array_elements(g.input_payload->'eventInputs') e
 cross join lateral jsonb_array_elements(e.value->'members') m where e.value#>>'{event,id}'=target->>'event_id'
 and m.value#>>'{article,id}'=relation->>'correcting_article_id' and m.value#>>'{article,reader_state}'='eligible'
 and m.value#>>'{article,source_status}'='active')
 or nullif(btrim(relation->>'correction_text'),'') is null then raise exception 'mip_publication_correction_ineligible';end if;
 corrections:=corrections||jsonb_build_array(relation||jsonb_build_object('claim_key',target->>'claim_key'));
 end loop;
 return jsonb_set(o.output_payload,'{projection,explanations}',rev.explanations)
 ||jsonb_build_object('evidence_links',links,'corrections',corrections,'review_revision',rev.revision);

end $$;
create function mip_identity.stage_review(p_session uuid,p_runtime text,p_revision uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare rev mip_identity.publication_reviews;g comparison_qualification.generations;payload jsonb;prior uuid;
 dep uuid;ids uuid[]:='{}';keys text[]:='{}';relation record;item jsonb;k text;approved uuid;
begin
 perform mip_identity.authorize(p_session,p_runtime,'mip_projection_publisher_v1');
 perform 1 from mip_identity.collector_fence where id for share;
 perform 1 from mip_cutover_authority.publication_fence where id for update;
 payload:=mip_identity.validate_review(p_revision);
 select * into strict rev from mip_identity.publication_reviews where revision=p_revision;
 select * into strict g from comparison_qualification.generations where id=rev.generation_id;
 perform comparison_qualification.require_source_scope(p_runtime,g.source_project);
 perform comparison_qualification.require_evaluated_implementation(p_runtime,g.implementation_ref);
 select approved_payload_id into prior from mip_identity.review_stages where review_revision=p_revision;
 if found then
 perform mip_cutover_authority.check_publication_payload(prior);
 perform mip_identity.authorize(p_session,p_runtime,'mip_projection_publisher_v1');return prior;end if;
 -- Conservatively include every row in the retained relationship context, a superset
 -- of the transitive graph. Relationship insertion/deletion is therefore covered too.
 for relation in select * from jsonb_each(rev.relationship_context) loop
 for item in select value from jsonb_array_elements(relation.value) loop
 k:='source:'||relation.key||':'||comparison_qualification.argument_digest(item);
 insert into mip_cutover_authority.dependency_versions(dependency_key,source,children,record_hash,
 privacy_eligible,rights_eligible,retained_evidence,correction_current,explanation_eligible,publication_eligible,state,valid_until,predicate_version)
 values(k,g.source_project,'{}',comparison_qualification.argument_digest(item),true,true,true,true,true,true,'current',rev.valid_until,rev.policy_ref)
 returning id into dep;
 insert into mip_cutover_authority.dependency_heads values(k,dep) on conflict(dependency_key) do update set version_id=excluded.version_id;
 ids:=array_append(ids,dep);keys:=array_append(keys,k);
 end loop;end loop;
 k:='review:'||p_revision::text;
 insert into mip_cutover_authority.dependency_versions(dependency_key,source,children,record_hash,
 privacy_eligible,rights_eligible,retained_evidence,correction_current,explanation_eligible,publication_eligible,state,valid_until,predicate_version)
 values(k,g.source_project,keys,comparison_qualification.argument_digest(payload),true,true,true,true,true,true,'current',rev.valid_until,rev.policy_ref) returning id into dep;
 insert into mip_cutover_authority.dependency_heads values(k,dep);
 ids:=array_append(ids,dep);
 insert into mip_cutover_authority.approved_payloads(source,generation_id,payload,payload_hash,dependency_versions,owner_approval_ref)
 values(g.source_project,g.id,payload,comparison_qualification.argument_digest(payload),ids,rev.authorization_ref) returning id into approved;
 perform mip_cutover_authority.select_approved_payload(approved);
 insert into mip_identity.review_stages values(p_revision,approved);
 perform mip_identity.validate_review(p_revision);
 perform mip_identity.authorize(p_session,p_runtime,'mip_projection_publisher_v1');
 return approved;
end $$;
create function mip_identity.release_isolated(p_request uuid,p_session uuid,p_runtime text,p_revision uuid) returns text
language plpgsql security definer set search_path='' as $$
declare approved uuid;payload jsonb;prior mip_identity.private_releases;
begin
 approved:=mip_identity.stage_review(p_session,p_runtime,p_revision);
 payload:=mip_cutover_authority.check_publication_payload(approved);
 select * into prior from mip_identity.private_releases where request_id=p_request;
 if found then
 if prior.runtime is distinct from p_runtime or prior.review_revision is distinct from p_revision then raise exception 'mip_publication_replay_conflict';end if;
 perform mip_identity.validate_review(p_revision);
 perform mip_identity.authorize(p_session,p_runtime,'mip_projection_publisher_v1');
 return 'isolated_released';end if;
 insert into mip_identity.private_releases(request_id,runtime,review_revision,approved_payload_id,payload_hash)
 values(p_request,p_runtime,p_revision,approved,comparison_qualification.argument_digest(payload));
 perform mip_identity.validate_review(p_revision);
 perform mip_identity.authorize(p_session,p_runtime,'mip_projection_publisher_v1');
 return 'isolated_released';
end $$;
create function mip_identity.release_public() returns void language plpgsql set search_path='' as $$
begin raise exception 'mip_public_release_disabled';end $$;

do $permissions$
declare t text;r record;
begin
 foreach t in array array['publication_policy_versions','publication_policy_heads','publication_reviews','publication_review_heads','review_stages','private_releases'] loop
 execute format('alter table mip_identity.%I owner to mip_cutover_schema_owner_v1',t);
 execute format('alter table mip_identity.%I enable row level security',t);
 execute format('alter table mip_identity.%I force row level security',t);
 execute format('revoke all on mip_identity.%I from public,anon,authenticated,service_role',t);
 execute format('grant select on mip_identity.%I to mip_publication_owner_v2',t);
 execute format('create policy publication_owner on mip_identity.%I to mip_publication_owner_v2 using(true) with check(true)',t);
 if t not in ('publication_review_heads','publication_policy_heads') then
 execute format('create trigger immutable before update or delete on mip_identity.%I for each row execute function comparison_qualification.reject_rewrite()',t);
 execute format('create trigger no_truncate before truncate on mip_identity.%I for each statement execute function comparison_qualification.reject_rewrite()',t);
 end if;end loop;
 for r in select p.oid::regprocedure::text sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='mip_identity'
 and p.proname in ('survivor_relations','survivor_context','invalidate_source_publications','validate_review','stage_review','release_isolated','release_public') loop
 execute 'alter function '||r.sig||' owner to mip_publication_owner_v2';
 execute 'revoke all on function '||r.sig||' from public,anon,authenticated,service_role';
 end loop;
 for r in select tablename from pg_tables where schemaname='mip_cutover_authority' loop
 execute format('alter table mip_cutover_authority.%I owner to mip_cutover_schema_owner_v1',r.tablename);
 execute format('alter table mip_cutover_authority.%I force row level security',r.tablename);
 end loop;
 foreach t in array array['publication_fence','dependency_versions','dependency_heads','approved_payloads','publication_selections'] loop
 execute format('grant select,insert,update on mip_cutover_authority.%I to mip_publication_owner_v2',t);
 execute format('create policy publication_kernel on mip_cutover_authority.%I to mip_publication_owner_v2 using(true) with check(true)',t);
 end loop;
 for r in select p.oid::regprocedure::text sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='mip_cutover_authority'
 and p.proname in ('fence_publication_write','check_publication_payload','select_approved_payload') loop
 execute 'alter function '||r.sig||' owner to mip_publication_owner_v2';
 end loop;
end $permissions$;
grant insert on mip_identity.review_stages,mip_identity.private_releases to mip_publication_owner_v2;
alter function mip_identity.install_survivor_fences() owner to mip_cutover_schema_owner_v1;
grant usage on schema mip_identity,mip_cutover_authority,comparison_qualification,public to mip_publication_owner_v2;
grant usage on schema mip_identity to mip_projection_publisher_v1;
grant select,update on mip_identity.collector_fence to mip_publication_owner_v2;
create policy publication_collector_fence on mip_identity.collector_fence to mip_publication_owner_v2 using(true) with check(true);
grant select on comparison_qualification.generations,comparison_qualification.outputs to mip_publication_owner_v2;
create policy publication_generation on comparison_qualification.generations for select to mip_publication_owner_v2 using(true);
create policy publication_output on comparison_qualification.outputs for select to mip_publication_owner_v2 using(true);
grant execute on function mip_identity.authorize(uuid,text,text),
 comparison_qualification.source_snapshot(jsonb,text),comparison_qualification.argument_digest(jsonb),
 comparison_qualification.require_source_scope(text,text),comparison_qualification.require_evaluated_implementation(text,text)
 to mip_publication_owner_v2;
grant execute on function mip_identity.stage_review(uuid,text,uuid),mip_identity.release_isolated(uuid,uuid,text,uuid) to mip_projection_publisher_v1;
revoke all on function mip_identity.install_survivor_fences() from public,anon,authenticated,service_role;
-- No worker grants on review records, staging, publisher APIs, source mutation or rule decisions.
commit;

-- Opt-in ISOLATED extension over 007. Not a production migration.
-- Reference cache, not a new policy authority. No actual source grants are seeded.
-- Only the explicitly synthetic adapter is presently bound; real records fail closed.
begin;
create table mip_identity.operation_evidence_versions(
 revision uuid primary key, scope jsonb not null,
 authority_adapter text not null,
 source_ref text not null, source_version text not null, source_hash text not null,
 evidence_ref text not null, approval_owner_ref text not null, approval_record_ref text not null,
 approval_status text not null check(approval_status in ('recorded','proposed','missing','conflicting')),
 disposition text not null check(disposition in ('allow','deny','unknown','conflicting','withdrawn')),
 effective_at timestamptz not null check(isfinite(effective_at)),
 expires_at timestamptz not null check(isfinite(expires_at) and expires_at>effective_at),
 conditions jsonb not null check(jsonb_typeof(conditions)='array'),
 synthetic boolean not null,
 unique(scope,revision),
 check(jsonb_typeof(scope)='object' and scope ?& array['source_project','material_ref','material_version','operation','audience','domain']),
 check(scope->>'operation' in ('ingestion','retention','analysis','excerpt_display','full_content_display','redistribution','external_model_disclosure')),
 check(scope->>'domain' in ('rights','privacy')),
 check(length(scope->>'source_project')>0 and length(scope->>'material_ref')>0 and length(scope->>'material_version')>0 and length(scope->>'audience')>0)
);
create table mip_identity.operation_evidence_heads(
 scope jsonb primary key, revision uuid not null, active boolean not null,
 foreign key(scope,revision) references mip_identity.operation_evidence_versions(scope,revision)
);
create table mip_identity.review_operation_bindings(
 review_revision uuid primary key references mip_identity.publication_reviews,
 decision_revisions uuid[] not null
);
create trigger operation_fence before insert or update or delete or truncate on mip_identity.operation_evidence_heads
 for each statement execute function mip_cutover_authority.fence_publication_write();
create trigger operation_retirement before insert or update or delete on mip_identity.operation_evidence_heads
 for each row execute function mip_identity.guard_revision_reuse();
create trigger operation_no_truncate before truncate on mip_identity.operation_evidence_heads
 for each statement execute function comparison_qualification.reject_rewrite();

create function mip_identity.operation_check(p_scope jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v mip_identity.operation_evidence_versions; h mip_identity.operation_evidence_heads; reason text;
begin
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 select * into h from mip_identity.operation_evidence_heads where scope=p_scope;
 if not found then return jsonb_build_object('allowed',false,'reason','missing_operation_evidence','scope',p_scope);end if;
 select * into strict v from mip_identity.operation_evidence_versions where revision=h.revision;
 if not h.active then reason:='revoked_operation_evidence';
 elsif v.approval_status<>'recorded' then reason:='approval_'||v.approval_status;
 elsif v.disposition<>'allow' then reason:='permission_'||v.disposition;
 elsif v.effective_at>clock_timestamp() then reason:='permission_not_effective';
 elsif v.expires_at<=clock_timestamp() then reason:='permission_expired';
 elsif nullif(btrim(v.source_ref),'') is null or nullif(btrim(v.source_version),'') is null
 or v.source_hash !~ '^[0-9a-f]{64}$' or nullif(btrim(v.evidence_ref),'') is null
 or nullif(btrim(v.approval_owner_ref),'') is null or nullif(btrim(v.approval_record_ref),'') is null
 then reason:='unsupported_evidence_reference';
 elsif exists(select 1 from jsonb_array_elements(v.conditions) c
 where jsonb_typeof(c)<>'object' or c->>'status' is distinct from 'verified'
 or nullif(btrim(c->>'evidence_ref'),'') is null)
 then reason:='unfulfilled_permission_condition';
 -- Strings, URLs and a database row cannot authenticate an actual permission.
 -- Binding an authoritative record reader is still required before non-synthetic use.
 elsif not v.synthetic or v.authority_adapter<>'synthetic-fixture-v1' then reason:='authoritative_adapter_unbound';
 else reason:='synthetic_mechanism_only';end if;
 return jsonb_build_object('allowed',reason='synthetic_mechanism_only','reason',reason,
 'scope',p_scope,'revision',v.revision,'synthetic',v.synthetic,'source_ref',v.source_ref,
 'source_version',v.source_version,'evidence_ref',v.evidence_ref,'approval_record_ref',v.approval_record_ref);
end $$;

alter function mip_identity.validate_review(uuid) rename to validate_review_predicates_v1;
create function mip_identity.validate_review(p_revision uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare payload jsonb;g comparison_qualification.generations; member jsonb;op text;domain text;
 scope jsonb;checked jsonb;revisions uuid[]:='{}';prior uuid[];
begin
 -- Preserve all stricter 007 evidence/privacy/correction/source and topology checks.
 payload:=mip_identity.validate_review_predicates_v1(p_revision);
 select gen.* into strict g from comparison_qualification.generations gen
 join mip_identity.publication_reviews r on r.generation_id=gen.id where r.revision=p_revision;
 for member in select distinct m.value->'article' from jsonb_array_elements(g.input_payload->'eventInputs') e
 cross join lateral jsonb_array_elements(e.value->'members') m loop
 foreach op in array array['retention','analysis','excerpt_display'] loop
 foreach domain in array array['rights','privacy'] loop
 scope:=jsonb_build_object('source_project',g.source_project,'material_ref','article:'||(member->>'id'),
 'material_version',comparison_qualification.argument_digest(member),'operation',op,'audience','isolated_internal_review','domain',domain);
 checked:=mip_identity.operation_check(scope);
 if checked->'allowed' is distinct from 'true'::jsonb then
 raise exception 'mip_operation_denied_%',checked->>'reason' using detail=checked::text;end if;
 revisions:=array_append(revisions,(checked->>'revision')::uuid);
 end loop;end loop;end loop;
 if cardinality(revisions)=0 then raise exception 'mip_operation_denied_missing_material_closure';end if;
 select array_agg(distinct r order by r) into revisions from unnest(revisions) r;
 select decision_revisions into prior from mip_identity.review_operation_bindings where review_revision=p_revision;
 if found and prior is distinct from revisions then raise exception 'mip_operation_fresh_review_required';end if;
 insert into mip_identity.review_operation_bindings values(p_revision,revisions) on conflict do nothing;
 return payload;
end $$;

do $permissions$
declare t text;f text;
begin
 foreach t in array array['operation_evidence_versions','operation_evidence_heads','review_operation_bindings'] loop
 execute format('alter table mip_identity.%I owner to mip_cutover_schema_owner_v1',t);
 execute format('alter table mip_identity.%I enable row level security',t);
 execute format('alter table mip_identity.%I force row level security',t);
 execute format('revoke all on mip_identity.%I from public,anon,authenticated,service_role,mip_comparison_worker_v1,mip_comparison_producer_v1,mip_projection_publisher_v1',t);
 execute format('grant select on mip_identity.%I to mip_publication_owner_v2',t);
 execute format('create policy operation_reader on mip_identity.%I to mip_publication_owner_v2 using(true) with check(true)',t);
 if t<>'operation_evidence_heads' then
 execute format('create trigger immutable before update or delete on mip_identity.%I for each row execute function comparison_qualification.reject_rewrite()',t);
 execute format('create trigger no_truncate before truncate on mip_identity.%I for each statement execute function comparison_qualification.reject_rewrite()',t);
 end if;
 end loop;
 foreach f in array array['operation_check(jsonb)','validate_review(uuid)','validate_review_predicates_v1(uuid)'] loop
 execute 'alter function mip_identity.'||f||' owner to mip_publication_owner_v2';
 execute 'revoke all on function mip_identity.'||f||' from public,anon,authenticated,service_role,mip_comparison_worker_v1,mip_comparison_producer_v1,mip_projection_publisher_v1';
 end loop;
end $permissions$;
grant insert on mip_identity.review_operation_bindings to mip_publication_owner_v2;
commit;

-- Disposable-only extension over 007/008. No production installation or public release.
begin;
create schema mip_factual;
create schema mip_factual_transport;
create extension dblink with schema mip_factual_transport;
do $$begin
 if not exists(select 1 from pg_roles where rolname='mip_factual_owner_v3') then create role mip_factual_owner_v3 nologin nosuperuser nobypassrls;end if;
 if not exists(select 1 from pg_roles where rolname='mip_factual_reviewer_v3') then create role mip_factual_reviewer_v3 nologin nosuperuser nobypassrls;end if;
end $$;
create table mip_factual.audit_connection(id boolean primary key check(id),connection_string text not null);
-- Separate connection commits before the rejecting transaction raises; no outer-row FK.
create table mip_factual.rejection_audit(
 id uuid primary key,explanation_id uuid not null,assertion_digest text not null,
 attempted_transition text not null check(attempted_transition='published'),
 rule text not null check(rule in ('provenance','human_review','source_state')),
 recorded_at timestamptz not null default clock_timestamp()
);
create table mip_factual.human_reviews(
 id uuid primary key default gen_random_uuid(),explanation_id uuid not null,
 record_hash text not null,source_hash text not null,approval_ref text not null check(length(btrim(approval_ref))>0),
 reviewer_role text not null,recorded_at timestamptz not null default clock_timestamp()
);
create table mip_factual.explanation_history(
 id uuid primary key default gen_random_uuid(),explanation_id uuid not null,
 row_data jsonb not null,recorded_at timestamptz not null default clock_timestamp()
);
create table mip_factual.source_changes(
 id uuid primary key,source_id uuid not null,change_kind text not null check(change_kind in ('corrected','withdrawn')),
 affected_ids uuid[] not null,skipped_withdrawn_ids uuid[] not null,
 actor_role text not null,recorded_at timestamptz not null default clock_timestamp()
);
create table mip_factual.source_change_links(
 change_id uuid not null references mip_factual.source_changes,
 prior_explanation_id uuid not null,new_explanation_id uuid not null,
 primary key(change_id,prior_explanation_id)
);
create function mip_factual.source_hash(ids uuid[]) returns text
language sql security definer set search_path='' as $$
 select comparison_qualification.argument_digest(coalesce(jsonb_agg(to_jsonb(a) order by a.id),'[]'::jsonb)) from public.articles a where a.id=any(ids);
$$;
create function mip_factual.record_hash(x jsonb) returns text
language sql immutable set search_path='' as $$
 select comparison_qualification.argument_digest(x-'review_status'-'state');
$$;
create function mip_factual.log_rejection(x jsonb,rule text) returns void
language plpgsql security definer set search_path='' as $$
declare conn text;
begin
 if rule not in ('provenance','human_review','source_state') then raise exception 'mip_audit_rule_invalid';end if;
 select connection_string into strict conn from mip_factual.audit_connection where id;
 -- Only UUID/digest/fixed code cross this boundary: never passages, source text, approval refs or SQL errors.
 perform mip_factual_transport.dblink_exec(conn,format(
 'insert into mip_factual.rejection_audit(id,explanation_id,assertion_digest,attempted_transition,rule) values(%L,%L,%L,''published'',%L)',
 gen_random_uuid(),(x->>'id')::uuid,comparison_qualification.argument_digest(jsonb_build_object('assertion_id',x->>'assertion_id')),rule));
exception when others then raise exception 'mip_audit_unavailable';
end $$;
create function mip_factual.guard_publication() returns trigger
language plpgsql security definer set search_path='' as $$
declare reason text;
begin
 if new.review_status<>'published' then return new;end if;
 perform 1 from mip_identity.collector_fence where id for share;
 perform 1 from mip_cutover_authority.publication_fence where id for update;
 if new.is_current is distinct from true or new.state is distinct from 'ok'
 or nullif(btrim(new.supporting_passage),'') is null
 or nullif(btrim(new.falsification_condition),'') is null or btrim(new.falsification_condition) ilike 'missing:%'
 or jsonb_typeof(new.archived_sources) is distinct from 'array' or jsonb_array_length(new.archived_sources)=0
 or exists(select 1 from jsonb_array_elements(new.archived_sources) s where s->>'status' is distinct from 'retained')
 then reason:='provenance';
 elsif cardinality(new.source_ids)=0 or new.source_ids is null or exists(
 select 1 from unnest(new.source_ids) s(source_id) left join public.articles a on a.id=s.source_id
 where a.id is null or a.source_status is distinct from 'active' or a.reader_state is distinct from 'eligible')
 then reason:='source_state';
 elsif not exists(select 1 from mip_factual.human_reviews r where r.explanation_id=new.id
 and r.record_hash=mip_factual.record_hash(to_jsonb(new)) and r.source_hash=mip_factual.source_hash(new.source_ids))
 then reason:='human_review';end if;
 if reason is not null then
 perform mip_factual.log_rejection(to_jsonb(new),reason);
 raise exception 'mip_factual_rejected_%',reason;
 end if;
 return new;
end $$;
create unique index factual_current_version on public.explanations(assertion_id) where is_current;
create unique index factual_version_identity on public.explanations(assertion_id,version);
create trigger factual_publication_guard before insert or update on public.explanations
 for each row execute function mip_factual.guard_publication();
create function mip_factual.retain_explanation() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'mip_factual_history_preserved';end if;
 if tg_op='UPDATE' then insert into mip_factual.explanation_history(explanation_id,row_data) values(old.id,to_jsonb(old));end if;
 return new;
end $$;
create trigger factual_history before update or delete on public.explanations for each row execute function mip_factual.retain_explanation();

create function mip_factual.review_publish(p_id uuid,p_approval text) returns void
language plpgsql security definer set search_path='' as $$
declare x public.explanations;
begin
 perform 1 from mip_identity.collector_fence where id for update;
 perform 1 from mip_cutover_authority.publication_fence where id for update;
 select * into strict x from public.explanations where id=p_id for update;
 if not x.is_current or x.review_status='withdrawn' then raise exception 'mip_factual_fresh_version_required';end if;
 insert into mip_factual.human_reviews(explanation_id,record_hash,source_hash,approval_ref,reviewer_role)
 values(x.id,mip_factual.record_hash(to_jsonb(x)),mip_factual.source_hash(x.source_ids),p_approval,session_user);
 update public.explanations set review_status='published',state='ok' where id=p_id;
end $$;

create function mip_factual.source_change() returns trigger
language plpgsql security definer set search_path='' as $$
declare x public.explanations;fresh public.explanations;event uuid:=gen_random_uuid();
 affected uuid[]:='{}';skipped uuid[]:='{}';
begin
 if new.source_status is not distinct from old.source_status or new.source_status not in ('corrected','withdrawn') then return new;end if;
 perform 1 from mip_cutover_authority.publication_fence where id for update;
 for x in select * from public.explanations where is_current and new.id=any(source_ids) order by id for update loop
 if x.review_status='withdrawn' then skipped:=array_append(skipped,x.id);continue;end if;
 affected:=array_append(affected,x.id);
 end loop;
 insert into mip_factual.source_changes values(event,new.id,new.source_status,affected,skipped,session_user,clock_timestamp());
 for x in select * from public.explanations where id=any(affected) order by id loop
 -- Archive the exact old row; old record remains available as a prior version.
 update public.explanations set is_current=false,review_status=case when review_status='published' then 'awaiting_review' else review_status end where id=x.id;
 fresh:=x;fresh.id:=gen_random_uuid();fresh.version:=x.version+1;fresh.is_current:=true;
 fresh.review_status:='awaiting_review';fresh.state:='source_'||new.source_status;
 insert into public.explanations select (fresh).*;
 insert into mip_factual.source_change_links values(event,x.id,fresh.id);
 end loop;
 return new;
end $$;
create trigger zz_factual_source_change before update on public.articles for each row execute function mip_factual.source_change();

-- Independent reader: does not rely on the publication trigger having run.
create view mip_factual.reader_explanations with (security_barrier=true) as
 select e.* from public.explanations e
 where e.is_current and e.review_status='published' and e.state='ok'
 and nullif(btrim(e.supporting_passage),'') is not null
 and nullif(btrim(e.falsification_condition),'') is not null
 and btrim(e.falsification_condition) not ilike 'missing:%'
 and jsonb_typeof(e.archived_sources)='array' and jsonb_array_length(e.archived_sources)>0
 and not exists(select 1 from jsonb_array_elements(e.archived_sources) s where s->>'status' is distinct from 'retained')
 and cardinality(e.source_ids)>0
 and not exists(select 1 from unnest(e.source_ids) s(source_id) left join public.articles a on a.id=s.source_id
 where a.id is null or a.source_status is distinct from 'active' or a.reader_state is distinct from 'eligible')
 and exists(select 1 from mip_factual.human_reviews r where r.explanation_id=e.id
 and r.record_hash=mip_factual.record_hash(to_jsonb(e)) and r.source_hash=mip_factual.source_hash(e.source_ids));

-- End-to-end staging retains all 007/008 predicates and additionally requires the factual reader.
alter function mip_identity.validate_review(uuid) rename to validate_review_operations_v2;
create function mip_identity.validate_review(p_revision uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;x jsonb;
begin
 result:=mip_identity.validate_review_operations_v2(p_revision);
 for x in select value from jsonb_array_elements(result#>'{projection,explanations}') loop
 if not exists(select 1 from mip_factual.reader_explanations e where e.assertion_id=x->>'assertion_id'
 and e.supporting_passage=x->>'supporting_passage' and e.rule_version=x->>'rule_version'
 and e.falsification_condition=x->>'falsification_condition' and e.archived_sources=x->'archived_sources')
 then raise exception 'mip_factual_release_ineligible';end if;
 end loop;return result;
end $$;
do $permissions$
declare t text;r record;
begin
 foreach t in array array['audit_connection','rejection_audit','human_reviews','explanation_history','source_changes','source_change_links'] loop
 execute format('alter table mip_factual.%I owner to mip_cutover_schema_owner_v1',t);
 execute format('alter table mip_factual.%I enable row level security',t);
 execute format('alter table mip_factual.%I force row level security',t);
 execute format('revoke all on mip_factual.%I from public,anon,authenticated,service_role',t);
 execute format('grant select,insert on mip_factual.%I to mip_factual_owner_v3',t);
 execute format('create policy factual_kernel on mip_factual.%I to mip_factual_owner_v3 using(true) with check(true)',t);
 if t<>'audit_connection' then
 execute format('create trigger immutable before update or delete on mip_factual.%I for each row execute function comparison_qualification.reject_rewrite()',t);
 execute format('create trigger no_truncate before truncate on mip_factual.%I for each statement execute function comparison_qualification.reject_rewrite()',t);
 end if;
 end loop;
 for r in select p.oid::regprocedure::text sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='mip_factual' loop
 execute 'alter function '||r.sig||' owner to mip_factual_owner_v3';
 execute 'revoke all on function '||r.sig||' from public,anon,authenticated,service_role';
 end loop;
end $permissions$;
revoke all on schema mip_factual,mip_factual_transport from public;
revoke all on all functions in schema mip_factual_transport from public;
grant usage on schema mip_factual,public,comparison_qualification,mip_identity,mip_cutover_authority,mip_factual_transport to mip_factual_owner_v3;
grant execute on function mip_factual_transport.dblink_exec(text,text) to mip_factual_owner_v3;
grant select,update on mip_identity.collector_fence,mip_cutover_authority.publication_fence to mip_factual_owner_v3;
create policy factual_collector_lock on mip_identity.collector_fence to mip_factual_owner_v3 using(true) with check(true);
create policy factual_release_lock on mip_cutover_authority.publication_fence to mip_factual_owner_v3 using(true) with check(true);
grant select on public.articles to mip_factual_owner_v3;
create policy factual_sources on public.articles for select to mip_factual_owner_v3 using(true);
grant select,insert,update on public.explanations to mip_factual_owner_v3;
alter table public.explanations enable row level security;
alter table public.explanations force row level security;
create policy factual_rows on public.explanations to mip_factual_owner_v3 using(true) with check(true);
create policy publication_rows on public.explanations for select to mip_publication_owner_v2 using(true);
grant execute on function comparison_qualification.argument_digest(jsonb) to mip_factual_owner_v3;
alter view mip_factual.reader_explanations owner to mip_factual_owner_v3;
grant usage on schema mip_factual to mip_factual_reviewer_v3,mip_publication_owner_v2,mip_cutover_schema_owner_v1;
grant execute on function mip_factual.review_publish(uuid,text) to mip_factual_reviewer_v3;
