import {spawn} from 'node:child_process'
export function guard(){
 if(process.env.GITHUB_ACTIONS!=='true'||process.env.MIP_DISPOSABLE_POSTGRES!=='comparison-qualification')
  throw Error('mip_disposable_environment_required')
}
export const quote=v=>v===null?'null':"'"+String(typeof v==='object'?JSON.stringify(v):v).replaceAll("'","''")+"'"
export function raw(database,sql){
 guard()
 return new Promise((resolve,reject)=>{
  const env=Object.fromEntries(Object.entries(process.env).filter(([k])=>!k.startsWith('PG')))
  Object.assign(env,{PGPASSWORD:'mip-disposable-ci-only',PGOPTIONS:'-c statement_timeout=20000 -c lock_timeout=15000',PGCONNECT_TIMEOUT:'5'})
  const child=spawn('psql',['-X','-qAt','-v','ON_ERROR_STOP=1','-v','VERBOSITY=verbose','-h','127.0.0.1','-p','5432','-U','postgres','-d',database],{env,stdio:['pipe','pipe','pipe']})
  let out='',err='';child.stdout.on('data',x=>out+=x);child.stderr.on('data',x=>err+=x)
  child.on('error',()=>reject(Error('mip_database_unavailable')))
  child.on('exit',code=>{
   if(code){
    const state=err.match(/ERROR:\s+([0-9A-Z]{5}):/)?.[1]??'unknown'
    const code=err.match(/ERROR:\s+(?:[0-9A-Z]{5}:\s+)?(mip_[a-z_]+)/)?.[1]
    const object=err.match(/permission denied for (?:table|schema|function) ([a-z_0-9]+)/)?.[1]
    const contexts=[...err.matchAll(/(?:PL\/pgSQL|SQL) function ([a-z_0-9.]+)/g)].map(x=>x[1]).filter(x=>/^(mip_|comparison_)/.test(x)).slice(0,5).join('_').replaceAll('.','_')
    const failure=Error((code??'mip_database_denied_'+state+(object?'_'+object:''))+(contexts?'_via_'+contexts:''))
    failure.code=state // Preserve only PostgreSQL SQLSTATE for the trusted handler; no query/payload text.
    reject(failure)
   }
   else resolve(out.trim())
  })
  child.stdin.end(sql)
 })
}
const names=new Set(['configuration','issue','journal_runtime','journal_put','journal_get','worker_claim','worker_complete','worker_fail','producer_enqueue','capture_delta','reconciliation','stage_review','release_isolated','release_public'])
export function transport(database,role){
 if(!/^[a-z_0-9]+$/.test(role))throw Error('mip_role_invalid')
 return async(name,args)=>{
  if(!names.has(name))throw Error('mip_rpc_invalid')
  const result=await raw(database,'set session authorization '+role+';select to_jsonb(mip_identity.'+name+'('+args.map(quote).join(',')+'));').catch(e=>{throw Error(e.message+'_'+name)})
  return result?JSON.parse(result):null
 }
}

import {spawn} from 'node:child_process'
import {guard,raw} from './transport.mjs'
export async function restartRemoteStore(){
 guard();const id=process.env.MIP_POSTGRES_SERVICE_ID
 if(!/^[a-f0-9]{12,64}$/.test(id??''))throw Error('mip_disposable_container_required')
 await new Promise((resolve,reject)=>{
  const p=spawn('docker',['restart','--time','5',id],{stdio:'ignore'})
  p.on('error',()=>reject(Error('mip_store_restart_failed')))
  p.on('exit',code=>code?reject(Error('mip_store_restart_failed')):resolve())
 })
 for(let n=0;n<40;n++){
  try{await raw('postgres','select 1');return}catch{}
  await new Promise(r=>setTimeout(r,250))
 }
 throw Error('mip_store_restart_timeout')
}

// Synthetic protocol bytes only. Native tests additionally consume PostgreSQL's actual output.
const b=(n,size)=>{const v=Buffer.alloc(size);size===8?v.writeBigUInt64BE(BigInt(n)):size===4?v.writeUInt32BE(Number(n)):v.writeUInt16BE(Number(n));return v}
const c=s=>Buffer.from(s+'\0'),byte=n=>Buffer.from([n])
export const epoch='11111111-1111-4111-8111-111111111111'
export function frames({relation=42,revision=epoch,xid=7,full='4294967303',commit=1000,end=1020,time=842529600123456n}={}){
 const columns=[['revision_id',2950,1],['epoch',2950,0],['creator_xid',5069,0]]
 return [
 Buffer.concat([byte(66),b(commit,8),b(time,8),b(xid,4)]),
 Buffer.concat([byte(82),b(relation,4),c('mip_hypothesis'),c('revision_transactions'),byte(100),b(3,2),
 ...columns.flatMap(([name,type,flag])=>[byte(flag),c(name),b(type,4),b(4294967295,4)])]),
 Buffer.concat([byte(73),b(relation,4),byte(78),b(3,2),...[revision,epoch,full].flatMap(v=>[byte(116),b(Buffer.byteLength(v),4),Buffer.from(v)])]),
 Buffer.concat([byte(67),byte(0),b(commit,8),b(end,8),b(time,8)])
 ]
}

import test from 'node:test'
import assert from 'node:assert/strict'
import {frames,epoch} from './hypothesisPgoutputFixture.mjs'
import {decodeMarkerBoundary,retainMarkerBoundary} from '../supabase/qualification/hypothesis-assessments/pgoutputBoundaryRecorder.mjs'
const options={relationId:'42',observationEpoch:epoch,markerId:epoch}
const context={source_id:epoch,stream_epoch:'22222222-2222-4222-8222-222222222222'}
const markerFrames=(args={})=>{
 const result=frames(args)
 result[1]=Buffer.from(result[1].toString('latin1').replace('mip_hypothesis','mip_temporal').replace('revision_transactions','stream_markers').replace('revision_id','marker_id'),'latin1')
 return result
}
const journal=()=>{const entries=new Map();return {entries,
 putOnce:async(k,v)=>{const text=JSON.stringify(v);if(entries.has(k)&&entries.get(k)!==text)throw Error('conflict');entries.set(k,text);return {committed:true}},
 get:async k=>entries.has(k)?JSON.parse(entries.get(k)):null}}
test('marker proof is a distinct native transaction with exact epoch, relation, xid and endpoint',()=>{
 const b=decodeMarkerBoundary(markerFrames(),options)
 assert.equal(b.end_lsn,'0/3FC');assert.equal(b.creator_xid,'4294967303')
 assert.equal(b.historical_time_qualified,false);assert.equal(Object.hasOwn(b,'revisions'),false)
 for(const [data,opt] of [
  [[],options],[frames(),options],[markerFrames().slice(0,-1),options],
  [[...markerFrames(),...markerFrames()],options],
  [markerFrames(),{...options,markerId:context.stream_epoch}],
  [markerFrames(),{...options,observationEpoch:context.stream_epoch}],
  [markerFrames(),{...options,relationId:'43'}],
  [markerFrames({full:'4294967304'}),options],
  [markerFrames({end:999}),options]
 ])assert.throws(()=>decodeMarkerBoundary(data,opt),/mip_marker_boundary_denied/)
})
test('mutation, logical message, extra tuple, trailing bytes and commit mismatch fail closed',()=>{
 for(const index of [0,1,2,3]){
  const data=markerFrames();data[index]=Buffer.concat([data[index],Buffer.from([0])])
  assert.throws(()=>decodeMarkerBoundary(data,options))
 }
 for(const kind of [77,85,68,84,83]){
  const data=markerFrames();data[2][0]=kind
  assert.throws(()=>decodeMarkerBoundary(data,options))
 }
 const data=markerFrames();data[3][9]^=1
 assert.throws(()=>decodeMarkerBoundary(data,options))
})
test('retention requires committed exact readback, immutable retry and never acknowledges',async()=>{
 const j=journal(),data=markerFrames()
 const args={...options,context,frames:data,journal:j}
 const result=await retainMarkerBoundary(args)
 assert.equal(result.state,'durable_marker_boundary_proof')
 assert.equal(result.authority_integrated,false);assert.equal(result.historical_time_qualified,false)
 assert.deepEqual(await retainMarkerBoundary(args),result)
 await assert.rejects(()=>retainMarkerBoundary({...args,frames:markerFrames({time:842529600123457n})}),/conflict/)
 await assert.rejects(()=>retainMarkerBoundary({...args,journal:{putOnce:async()=>({committed:false}),get:j.get}}),/not_durable/)
 await assert.rejects(()=>retainMarkerBoundary({...args,journal:{putOnce:j.putOnce,get:async()=>null}}),/not_durable/)
})
test('caller mutation during custody cannot change retained source or native transcript',async()=>{
 const j=journal(),data=markerFrames(),scope={...context}
 const result=await retainMarkerBoundary({...options,context:scope,frames:data,journal:{
  putOnce:async(k,v)=>{scope.source_id=context.stream_epoch;data[0].fill(0);return j.putOnce(k,v)},get:j.get}})
 assert.equal((await j.get(result.key)).source_id,context.source_id)
 assert.equal((await j.get(result.key)).frames[0][0],'4')
})

test('custody adapter mutation cannot alter the returned endpoint after retaining original bytes',async()=>{
 const j=journal()
 let adapterObject
 const result=await retainMarkerBoundary({...options,context,frames:markerFrames(),journal:{
  putOnce:async(k,v)=>{adapterObject=v;const receipt=await j.putOnce(k,v);v.boundary.end_lsn='F/FFFFFF';return receipt},
  get:async k=>{adapterObject.boundary.end_lsn='E/EEEEEE';return j.get(k)}
 }})
 const retained=await j.get(result.key)
 assert.equal(result.end_lsn,retained.boundary.end_lsn)
 assert.equal(result.end_lsn,'0/3FC')
})

// Synthetic paged snapshot mechanism fixtures, not material or semantic qualification.
import test from 'node:test'
import assert from 'node:assert/strict'
import {recordPagedBootstrap,validateBootstrapCoverage,bootstrapKey,bootstrapPageKey,recordBootstrappedPgoutputBatch} from '../supabase/qualification/hypothesis-assessments/temporalBootstrap.mjs'
import {epoch,frames} from './hypothesisPgoutputFixture.mjs'
const context={source_id:epoch,stream_epoch:epoch},input={consistent_lsn:'0/10',snapshot_id:'00000003-000000AA-1'}
const row=i=>({revision_id:'00000000-0000-4000-8000-'+i.toString(16).padStart(12,'0'),transaction_epoch:null,creator_xid:null})
function fixture(rows){
 const entries=new Map()
 const journal={putOnce:async(k,v)=>{const text=JSON.stringify(v);if(entries.has(k)&&entries.get(k)!==text)throw Error('synthetic_conflict');entries.set(k,text);return {committed:true}},
  get:async k=>entries.has(k)?JSON.parse(entries.get(k)):null}
 const withSnapshot=async(id,consume)=>{let at=0;await consume(async n=>{const page=rows.slice(at,at+n);at+=page.length;return page});return {snapshot_id:id,read_transaction_completed:true}}
 return {entries,options:{context,observationEpoch:epoch,input,journal,withSnapshot,pageSize:2}}
}
test('paged snapshot exceeds old single-envelope bound without truncation and validates a late-page overlap',async()=>{
 const f=fixture(Array.from({length:100001},(_,i)=>row(i+1)));f.options.pageSize=10000
 const result=await recordPagedBootstrap(f.options)
 assert.equal(result.revisions,100001);assert.equal(result.pages,11)
 const validated=await validateBootstrapCoverage({...f.options,revisionIds:[row(100001).revision_id]})
 assert.equal(validated.revisions,100001);assert.equal(validated.overlap,true)
 assert.equal((await recordPagedBootstrap(f.options)).hash,result.hash)
})
test('paged capture preserves null and foreign transaction provenance and exact empty baseline',async()=>{
 const rows=[row(1),{...row(2),transaction_epoch:'22222222-2222-4222-8222-222222222222',creator_xid:'9'}],f=fixture(rows)
 await recordPagedBootstrap(f.options)
 const page=await f.options.journal.get(bootstrapPageKey(context,0))
 assert.deepEqual(page.bootstrap.rows.map(r=>r.provenance),['transaction_not_established','foreign_transaction_epoch'])
 const empty=fixture([]),result=await recordPagedBootstrap(empty.options)
 assert.equal(result.revisions,0);assert.equal(result.pages,0)
 assert.equal((await validateBootstrapCoverage(empty.options)).overlap,false)
})
test('interrupted or unconfirmed read transaction retains pages without completing a bootstrap manifest',async()=>{
 for(const kind of ['error','incomplete','wrong_snapshot','not_entered']){
  const f=fixture([row(1),row(2),row(3)]),reader=f.options.withSnapshot
  f.options.withSnapshot=async(id,consume)=>{
   if(kind==='not_entered')return {snapshot_id:id,read_transaction_completed:true}
   if(kind==='error'){let calls=0;await consume(async()=>{if(calls++)throw Error('synthetic_reader_terminated');return [row(1)]})}
   const done=await reader(id,consume)
   return {...done,read_transaction_completed:kind!=='incomplete',snapshot_id:kind==='wrong_snapshot'?'synthetic-wrong':id}
  }
  await assert.rejects(()=>recordPagedBootstrap(f.options))
  assert.equal(await f.options.journal.get(bootstrapKey(context)),null)
  if(kind!=='not_entered')assert.ok(f.entries.size>0)
 }
})
test('duplicate, reordered or overlapping pages deny a manifest rather than fabricating equivalence',async()=>{
 for(const rows of [[row(2),row(1)],[row(1),row(2),row(2)],[row(1),row(3),row(2)]]){
  const f=fixture(rows);await assert.rejects(()=>recordPagedBootstrap(f.options))
  assert.equal(await f.options.journal.get(bootstrapKey(context)),null)
 }
})
test('missing, changed, reordered and truncated page chains cannot acknowledge a stream',async()=>{
 for(const kind of ['missing','changed','reordered','truncated','count']){
  const f=fixture([row(1),row(2),row(3)]);await recordPagedBootstrap(f.options)
  const key=bootstrapKey(context),p0=bootstrapPageKey(context,0),p1=bootstrapPageKey(context,1)
  if(kind==='missing')f.entries.delete(p1)
  if(kind==='changed'){const v=JSON.parse(f.entries.get(p1));v.bootstrap.rows[0].creator_xid='8';f.entries.set(p1,JSON.stringify(v))}
  if(kind==='reordered'){const v=f.entries.get(p0);f.entries.set(p0,f.entries.get(p1));f.entries.set(p1,v)}
  if(kind==='truncated'){const v=JSON.parse(f.entries.get(key));v.page_count=0;v.row_count=0;v.last_page_hash=null;f.entries.set(key,JSON.stringify(v))}
  if(kind==='count'){const v=JSON.parse(f.entries.get(key));v.row_count++;f.entries.set(key,JSON.stringify(v))}
  let acknowledged=false
  await assert.rejects(()=>recordBootstrappedPgoutputBatch({...f.options,frames:frames(),relationId:'42',acknowledge:async()=>{acknowledged=true}}))
  assert.equal(acknowledged,false)
 }
})
test('page writes and final manifest both require committed exact readback',async()=>{
 for(const target of ['page','manifest']){
  const f=fixture([row(1)]),old=f.options.journal
  f.options.journal={get:old.get,putOnce:async(k,v)=>{await old.putOnce(k,v);return {committed:target==='page'?!k.includes(':page:'):k.includes(':page:')}}}
  await assert.rejects(()=>recordPagedBootstrap(f.options),/mip_bootstrap_not_durable/)
 }
})

create role anon; create role authenticated; create role service_role bypassrls;
create schema spatial;
create table public.articles (
  id uuid primary key default gen_random_uuid(), feed text not null, outlet text not null, title text not null, url text not null unique,
  summary text, body_text text, published_at timestamptz, fetched_at timestamptz not null default now(),
  ingestion_run_id text, reader_state text not null default 'pending_review' check(reader_state in ('eligible','pending_review','withheld')),
  source_status text not null default 'active' check(source_status in ('active','corrected','withdrawn')), claims jsonb default '[]'
);
create table public.nodes (id uuid primary key default gen_random_uuid(), type text not null, label text, metadata jsonb default '{}');
create table public.geographic_places (id uuid primary key default gen_random_uuid(), canonical_name text);
create table public.pipeline_config (key text primary key, value jsonb);
create table spatial.assertions (id uuid primary key default gen_random_uuid(), graph_node_id uuid references public.nodes(id));
create table spatial.assertion_revisions (id uuid primary key default gen_random_uuid(), spatial_assertion_id uuid references spatial.assertions(id), canonical_place_id uuid references public.geographic_places(id));
create view public.spatial_projection_v1 as select r.id revision_id,r.canonical_place_id,a.graph_node_id subject_graph_node_id
  from spatial.assertion_revisions r join spatial.assertions a on a.id=r.spatial_assertion_id;
grant usage on schema public to anon, authenticated, service_role;
grant select on public.nodes,public.geographic_places,public.spatial_projection_v1 to service_role;
alter table public.articles enable row level security;
grant select on public.articles to anon,authenticated;
create policy reader_eligibility on public.articles for select to anon,authenticated using(reader_state='eligible' and source_status='active');

